window.__texto({"id": "697065786", "paragrafos": [{"c": "identifica", "t": "PORTARIA Nº 62, DE 31 DE MARÇO DE 2026"}, {"c": "ementa", "t": "Aprova a Instrução Normativa Inmetro e os Requisitos de Avaliação da Conformidade para os Serviços Próprios de Inspeção de Equipamentos - Consolidado."}, {"c": "dou-paragraph", "t": "O PRESIDENTE DO INSTITUTO NACIONAL DE METROLOGIA, QUALIDADE E TECNOLOGIA - INMETRO, no exercício da competência que lhe foi outorgada pelos artigos 4º, § 2º, da Lei nº 5.966, de 11 de dezembro de 1973, e 3º, incisos I e IV, da Lei nº 9.933, de 20 de dezembro de 1999, combinados com o disposto no artigo 18, inciso V, do Anexo I ao Decreto nº 11.221, de 5 de outubro de 2022, considerando a Consulta Pública nº 17, de 21 de novembro de 2024, publicada no DOU de 11 de dezembro de 2024, página 58, e o que consta no Processo SEI nº 0052600.011368/2022-51, resolve:"}, {"c": "dou-paragraph", "t": "Objeto e âmbito de aplicação"}, {"c": "dou-paragraph", "t": "Art. 1º Ficam aprovados a Instrução Normativa Inmetro e os Requisitos de Avaliação da Conformidade para Serviços Próprios de Inspeção de Equipamentos - SPIE, fixados, respectivamente, nos Anexos I e II desta Portaria."}, {"c": "dou-paragraph", "t": "§1º A avaliação da conformidade de Serviços Próprios de Inspeção de Equipamentos - SPIE, de caráter voluntário, por meio do mecanismo de certificação, deve ser realizada por Organismo de Certificação de Produtos - OCP, estabelecido no Brasil e acreditado pelo Inmetro, consoante os Requisitos ora aprovados."}, {"c": "dou-paragraph", "t": "§2º Aplicam-se os presentes Requisitos aos Serviços Próprios de Inspeção de Equipamentos abrangidos pela Norma Regulamentadora nº 13 (NR-13) - Caldeiras, Vasos de Pressão, Tubulações e Tanques Metálicos de Armazenamento, aprovada pela Portaria MTb nº 3.214, de 8 de junho de 1978, em sua redação atual, conforme seu item 13.2.2, podendo também ser estendidos a outros equipamentos e sistemas pressurizados que ofereçam risco à integridade física dos trabalhadores, nos termos do item 13.2.3 da referida Norma."}, {"c": "dou-paragraph", "t": "Art. 2º Não compete ao Inmetro o exercício do poder de polícia administrativa quanto ao objeto, cabendo, exclusivamente, a supervisão quanto ao uso da marca, tendo por foco o cumprimento das regras de Avaliação da Conformidade."}, {"c": "dou-paragraph", "t": "Prazos e disposições transitórias"}, {"c": "dou-paragraph", "t": "Art. 3º A publicação desta Portaria não implica na necessidade de que seja iniciado novo processo de certificação com base nos requisitos ora consolidados."}, {"c": "dou-paragraph", "t": "§1º. Os certificados já emitidos deverão ser revisados, para referência à Portaria ora publicada, na próxima etapa de avaliação, considerado como limite a data de revogação prevista no art. 4º."}, {"c": "dou-paragraph", "t": "§2º Caso haja solicitação de uso da metodologia de Inspeção Não Intrusiva (INI) ou de adoção de Sistemas Instrumentados de Segurança (SIS) pelo SPIE certificado, a adequação referida no caput deve ocorrer mediante auditoria de escopo específico, conforme aplicável."}, {"c": "dou-paragraph", "t": "Cláusula de revogação"}, {"c": "dou-paragraph", "t": "Art. 4º Ficam revogadas, no prazo de 12 (doze) meses contados da data de vigência desta Portaria, as Portarias Inmetro:"}, {"c": "dou-paragraph", "t": "I - nº 537, de 21 de outubro de 2015, publicada no Diário Oficial da União de 23 de outubro de 2015, seção 1, página 80;"}, {"c": "dou-paragraph", "t": "II - nº 582, de 23 de novembro de 2015, publicada no Diário Oficial da União de 25 de novembro de 2015, seção 1, página 57;"}, {"c": "dou-paragraph", "t": "III - nº 177, de 1º de agosto de 2023, publicada no Diário Oficial da União de 1º de agosto de 2023, seção 1, página 33; e"}, {"c": "dou-paragraph", "t": "IV - nº 382, de 25 de agosto de 2023, publicada no Diário Oficial da União de 25 de agosto de 2023, seção 1 - Extra A, página 1."}, {"c": "dou-paragraph", "t": "Vigência"}, {"c": "dou-paragraph", "t": "Art. 5º Esta Portaria entra em vigor na data de sua publicação no Diário Oficial da União."}, {"c": "assina", "t": "MARCIO ANDRE OLIVEIRA BRITO"}, {"c": "anexo", "t": "ANEXO I - INSTRUÇÃO NORMATIVA INMETRO PARA SERVIÇOS PRÓPRIOS DE INSPEÇÃO DE EQUIPAMENTOS"}, {"c": "dou-paragraph", "t": "1. OBJETIVO"}, {"c": "dou-paragraph", "t": "Esta Instrução Normativa do Inmetro (INI-SPIE) estabelece os requisitos para os Serviços Próprios de Inspeção de Equipamentos (SPIE), conforme a Norma Regulamentadora 13 (NR-13) do Ministério do Trabalho e Emprego (MTE), nos aspectos relacionados à instalação, inspeção, operação e manutenção, visando a segurança e saúde dos trabalhadores."}, {"c": "dou-paragraph", "t": "2. SIGLAS"}, {"c": "dou-paragraph", "t": "Para fins desta Instrução Normativa Inmetro, são adotadas as siglas a seguir, complementadas pelas contidas nos documentos citados no item 3."}, {"c": "", "t": "CIPA"}, {"c": "", "t": "Comissão Interna de Prevenção de Acidentes e de Assédio"}, {"c": "", "t": "END"}, {"c": "", "t": "Ensaios Não Destrutivos"}, {"c": "", "t": "IBR (RBI)"}, {"c": "", "t": "Inspeção Baseada em Risco"}, {"c": "", "t": "INI"}, {"c": "", "t": "Inspeção Não Intrusiva"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Instrução Normativa Inmetro para SPIE"}, {"c": "", "t": "MTE"}, {"c": "", "t": "Ministério do Trabalho e Emprego"}, {"c": "", "t": "NC"}, {"c": "", "t": "Não Conformidade"}, {"c": "", "t": "PLH"}, {"c": "", "t": "Profissional Legalmente Habilitado"}, {"c": "", "t": "SIS"}, {"c": "", "t": "Sistema Instrumentado de Segurança para Caldeiras"}, {"c": "", "t": "SGC"}, {"c": "", "t": "Sistema de Gerenciamento de Combustão de caldeiras"}, {"c": "", "t": "SPIE"}, {"c": "", "t": "Serviço Próprio de Inspeção de Equipamentos"}, {"c": "", "t": "HH"}, {"c": "", "t": "Homem - Hora"}, {"c": "dou-paragraph", "t": "3. DOCUMENTOS COMPLEMENTARES"}, {"c": "dou-paragraph", "t": "3.1 Para fins desta INI-SPIE são adotados os documentos complementares a seguir."}, {"c": "", "t": "ABNT NBR 14842"}, {"c": "", "t": "Soldagem - Critérios para a qualificação e certificação de inspetores para o setor de petróleo e gás, petroquímico, fertilizantes, naval e termogeração (exceto nuclear)."}, {"c": "", "t": "ABNT NBR 15218"}, {"c": "", "t": "Critérios para Qualificação e Certificação de Inspetores de Pintura Industrial."}, {"c": "", "t": "ABNT NBR 16455"}, {"c": "", "t": "Vasos de pressão - Metodologia para Inspeção Não Intrusiva."}, {"c": "", "t": "ABNT NBR IEC 61511-1"}, {"c": "", "t": "Segurança funcional - Sistemas instrumentados de segurança para o setor da indústria de processo Parte 1: Estrutura, definições, sistema, hardware e requisitos de programação do aplicativo."}, {"c": "", "t": "ABNT NBR NM ISO 9712"}, {"c": "", "t": "Ensaios não destrutivos - Qualificação e certificação de pessoal em END."}, {"c": "", "t": "NR-01"}, {"c": "", "t": "Norma Regulamentadora 01 do Ministério do Trabalho e Emprego - Disposições Gerais e Gerenciamento de Riscos Ocupacionais."}, {"c": "", "t": "NR-13"}, {"c": "", "t": "Norma Regulamentadora 13 do Ministério do Trabalho e Emprego - Caldeiras, Vasos de Pressão, Tubulações e Tanques Metálicos de Armazenamento."}, {"c": "dou-paragraph", "t": "3.2 Devem ser utilizadas as versões atualizadas dos documentos e das normas citadas, ou suas substitutivas (em caso de cancelamento)."}, {"c": "dou-paragraph", "t": "3.2.1 O prazo para a adoção da versão mais atualizada da norma ou sua substitutiva é de 12 (doze) meses ou o prazo de adequação da própria norma, devendo ser adotado o menor desses 2 (dois) prazos."}, {"c": "dou-paragraph", "t": "3.2.2 O prazo para a adoção da versão mais atualizada das NR citadas é o prazo estabelecido pelo MTE."}, {"c": "dou-paragraph", "t": "4. DEFINIÇÕES"}, {"c": "dou-paragraph", "t": "Para fins desta INI-SPIE, são adotadas as definições a seguir, complementadas por aquelas contidas nos documentos citados no item 3."}, {"c": "dou-paragraph", "t": "4.1 Acidente maior"}, {"c": "dou-paragraph", "t": "Todo evento de grande magnitude como um vazamento, um incêndio ou uma explosão envolvendo uma ou mais substâncias perigosas que envolvam equipamentos controlados pelo SPIE e que exponha os trabalhadores, a população ou o meio ambiente a perigo de consequências imediatas ou de médio e longo prazos."}, {"c": "dou-paragraph", "t": "4.2 Aparelhagem"}, {"c": "dou-paragraph", "t": "Termo genérico utilizado para caracterizar qualquer tipo de equipamento, instrumento de medição, dispositivo, bloco padrão, material de consumo, utilizados na inspeção de equipamentos."}, {"c": "dou-paragraph", "t": "4.3 Auditoria interna"}, {"c": "dou-paragraph", "t": "Auditoria realizada periodicamente pelo estabelecimento para avaliar a conformidade do SPIE com as exigências desta Instrução Normativa de SPIE."}, {"c": "dou-paragraph", "t": "4.4 Calibração"}, {"c": "dou-paragraph", "t": "Conjunto de operações que estabelece, sob condições especificadas, a relação entre os valores indicados por um instrumento de medição ou sistema de medição ou valores representados por uma medida ou um material de referência, e os valores correspondentes das grandezas estabelecidas por padrões."}, {"c": "dou-paragraph", "t": "4.5 Duto Terrestre"}, {"c": "dou-paragraph", "t": "Tubulação projetada por códigos específicos, destinada à transferência de fluidos entre instalações de estabelecimentos, distintos ou não, ocupando áreas de terceiros."}, {"c": "dou-paragraph", "t": "4.6 Equipamentos dinâmicos"}, {"c": "dou-paragraph", "t": "Aqueles que para cumprir a sua função apresentam componentes com partes móveis, com movimento alternativo ou rotativo tais como bombas, compressores e turbinas."}, {"c": "dou-paragraph", "t": "4.7 Equipamentos estáticos"}, {"c": "dou-paragraph", "t": "Equipamentos que não apresentam rotação ou movimento, tais como caldeiras, vasos de pressão, vasos de pressão com agitadores ou dispersores, trocadores de calor, geradores de vapor, reatores, torres de processo, tanques de estocagem e tubulações, dutos terrestres, fornos, torres de resfriamento, dispositivos de segurança, tochas e serpentinas para troca térmica, enquadrados ou não na NR-13."}, {"c": "dou-paragraph", "t": "4.8 Equipamentos de pequeno, médio e grande porte"}, {"c": "dou-paragraph", "t": "Classificação dos equipamentos controlados com base em critérios como volume, pressão de operação e capacidade térmica, considerando sua complexidade de inspeção."}, {"c": "dou-paragraph", "t": "4.9 Equipamentos de terceiros"}, {"c": "dou-paragraph", "t": "Equipamentos abrangidos pela NR-13 que não pertencem ao estabelecimento e que operam dentro de suas instalações (fixos, temporários ou móveis), conectados ou não aos equipamentos sob gestão do SPIE, cuja operação possa impactar a integridade, o desempenho ou a segurança das instalações e das pessoas."}, {"c": "dou-paragraph", "t": "4.10 Estabelecimento"}, {"c": "dou-paragraph", "t": "Conjunto de instalações industriais, coerentemente agrupadas, submetidas a uma gestão comum."}, {"c": "dou-paragraph", "t": "4.11 Inertização"}, {"c": "dou-paragraph", "t": "Substituição do conteúdo do equipamento por um fluido inerte para prevenção de reações perigosas."}, {"c": "dou-paragraph", "t": "4.12 Inspeção Baseada em Risco (IBR)"}, {"c": "dou-paragraph", "t": "Metodologia estruturada para tomada de decisão, executada por uma equipe especializada, baseada em requisitos estabelecidos por normalização técnica específica nacional ou internacional, para estabelecer o plano e o programa de inspeção, de acordo com uma avaliação do risco, considerando as possíveis causas, probabilidade e consequências de falhas."}, {"c": "dou-paragraph", "t": "Nota: Também denominada RBI (\"Risk Based Inspection\")"}, {"c": "dou-paragraph", "t": "4.13 Inspeção de recebimento ou fabricação"}, {"c": "dou-paragraph", "t": "Conjunto de atividades que visam verificar se as características dos equipamentos ou componentes que estão sendo adquiridos, abrangidos pelo escopo do SPIE, atendem às especificações estabelecidas."}, {"c": "dou-paragraph", "t": "4.14 Itens controlados pelo SPIE"}, {"c": "dou-paragraph", "t": "Conjunto de equipamentos cuja integridade é gerenciada e assegurada pelo SPIE, conforme critérios estabelecidos nesta INI-SPIE e documentos aplicáveis."}, {"c": "dou-paragraph", "t": "4.15 Pico de serviço"}, {"c": "dou-paragraph", "t": "Período que exige quantidade de mão de obra superior ao efetivo regular do SPIE."}, {"c": "dou-paragraph", "t": "4.16 Plano de Inspeção"}, {"c": "dou-paragraph", "t": "Descrição estruturada das atividades de inspeção, incluindo exames e testes a serem realizados, elaborada com base nos mecanismos de danos previsíveis e no histórico dos equipamentos."}, {"c": "dou-paragraph", "t": "4.17 Política de Inspeção"}, {"c": "dou-paragraph", "t": "Conjunto de diretrizes estabelecidas pela alta administração do estabelecimento, que orientam a gestão e execução das atividades de inspeção, expressando o compromisso institucional com a segurança operacional."}, {"c": "dou-paragraph", "t": "4.18 Procedimento"}, {"c": "dou-paragraph", "t": "Registro formal da execução de uma atividade ou processo, tendo como referência norma, padrão, manual, ou documento equivalente."}, {"c": "dou-paragraph", "t": "4.19 Programa de Inspeção"}, {"c": "dou-paragraph", "t": "Registro formal contendo as datas das últimas inspeções realizadas e os prazos estabelecidos para as próximas inspeções dos itens controlados pelo SPIE."}, {"c": "dou-paragraph", "t": "4.20 Prontuário do equipamento"}, {"c": "dou-paragraph", "t": "Documentação técnica fornecida pelo projetista, fabricante do equipamento, ou reconstituída pelo PLH, contendo os parâmetros utilizados no projeto, construção e montagem do equipamento."}, {"c": "dou-paragraph", "t": "4.21 Raqueteamento"}, {"c": "dou-paragraph", "t": "Bloqueio físico de uma tubulação ou equipamento utilizando um disco metálico ou Figura 8 que é inserido entre os flanges."}, {"c": "dou-paragraph", "t": "4.22 Recomendação de inspeção"}, {"c": "dou-paragraph", "t": "Documento emitido e controlado pelo SPIE, com base em constatações da inspeção realizada, contendo classificação de criticidade/risco e prazos limites de execução, visando à adoção de medidas para o restabelecimento das condições operacionais ou de projeto, ou para a manutenção da integridade do equipamento, tubulação, duto ou componente inspecionado. A Gestão do Estabelecimento é responsável por definir os órgãos responsáveis pela execução das ações recomendadas dentro dos prazos estabelecidos."}, {"c": "dou-paragraph", "t": "4.23 Responsável pelo Estabelecimento (Empregador)"}, {"c": "dou-paragraph", "t": "Proprietário do estabelecimento ou pessoa formalmente delegada por este, responsável pelo cumprimento das Normas Regulamentadoras do Ministério do Trabalho e Emprego, incluindo as obrigações relativas ao SPIE."}, {"c": "dou-paragraph", "t": "4.24 Serviços eventuais"}, {"c": "dou-paragraph", "t": "Serviços não rotineiros, com escopo e duração definidos, e que não justificam o aumento do efetivo próprio do SPIE."}, {"c": "dou-paragraph", "t": "4.25 Tubulações internas"}, {"c": "dou-paragraph", "t": "Conjunto de tubulações projetadas por códigos específicos para tubulação, destinada ao transporte de fluidos entre unidades industriais, de um mesmo estabelecimento, desde que dentro de um mesmo polo ou distrito industrial."}, {"c": "dou-paragraph", "t": "4.26 Tubulações externas"}, {"c": "dou-paragraph", "t": "Conjunto formado por tubulações e seus respectivos acessórios, projetados por códigos específicos, destinados ao transporte de fluidos entre unidades industriais de um mesmo estabelecimento ou entre estabelecimentos distintos, desde que percorram áreas externas ao perímetro das unidades de processo, como corredores técnicos, estruturas elevadas, áreas de utilidades ou faixas de terreno compartilhado ou de terceiros."}, {"c": "dou-paragraph", "t": "5. ESTRUTURA ORGANIZACIONAL DO SPIE"}, {"c": "dou-paragraph", "t": "5.1 O SPIE deve ser um órgão fisicamente constituído, dispor de recursos logísticos e aparelhagem compatíveis com as atividades desenvolvidas e constar da estrutura administrativa do estabelecimento, com atribuições, responsabilidades e autoridades de seus integrantes definidas formalmente. Profissionais do SPIE devem responder tecnicamente ao responsável pelo SPIE."}, {"c": "dou-paragraph", "t": "5.1.1 Responsável pelo SPIE"}, {"c": "dou-paragraph", "t": "O SPIE deve ter um responsável formalmente designado pelo empregador como seu representante, responsável pela gestão e implementação da política e do programa de inspeção de equipamentos. Este profissional deve compor o quadro do SPIE. A critério do estabelecimento e em função da complexidade da instalação, o responsável deve ou não ter dedicação exclusiva ao SPIE."}, {"c": "dou-paragraph", "t": "5.1.2 Independência do SPIE"}, {"c": "dou-paragraph", "t": "O responsável pelo SPIE deve possuir autonomia, credibilidade e autoridade suficientes para o exercício de suas funções e não pode exercer outras atividades que possam representar conflito de interesse ou comprometer a independência técnica do SPIE."}, {"c": "dou-paragraph", "t": "5.1.3 Efetivo e Qualificação de Pessoal do SPIE"}, {"c": "dou-paragraph", "t": "5.1.3.1 O SPIE deve possuir quadro de pessoal próprio, com escolaridade, formação e treinamento, compatíveis com suas atribuições, e com qualificação e certificação para atender as exigências legais e normativas."}, {"c": "dou-paragraph", "t": "5.1.3.2 Todos os integrantes, técnicos de inspeção e PLH, devem ter dedicação exclusiva ao SPIE no qual integram o efetivo conforme Anexo II da NR-13, podendo o PLH também ser o responsável pelo SPIE."}, {"c": "dou-paragraph", "t": "5.1.3.3 As atividades a serem desempenhadas pelo SPIE devem estar incluídas nas respectivas atribuições e responsabilidades."}, {"c": "dou-paragraph", "t": "5.1.3.4 Eventual prestação de serviço técnico de inspeção e engenharia em outro SPIE pode ser realizado desde que sem prejuízo ao atendimento do cumprimento dos programas de Inspeção do SPIE de origem."}, {"c": "dou-paragraph", "t": "5.1.3.4.1 O SPIE deve possuir, no mínimo, um PLH, que pode exercer outras funções, desde que sejam relacionadas às atividades de gestão de integridade de equipamentos estáticos e sem prejuízo ao atendimento do cumprimento dos programas de Inspeção do SPIE"}, {"c": "dou-paragraph", "t": "5.1.3.5 A quantidade de profissionais próprios do SPIE, incluindo inspetores de equipamentos, engenheiros e demais profissionais do SPIE, deve ser suficiente para a execução das atividades regulares de inspeção em condições normais de operação, conforme critérios definidos no Anexo A desta Instrução Normativa."}, {"c": "dou-paragraph", "t": "5.1.3.6 Na hipótese de o responsável pelo SPIE não atuar tecnicamente no SPIE, ele não pode ser considerado no cálculo de efetivo mínimo."}, {"c": "dou-paragraph", "t": "5.1.3.7 O Anexo B desta Instrução Normativa descreve os requisitos para a formação e capacitação dos inspetores de equipamentos."}, {"c": "dou-paragraph", "t": "5.1.3.8 O SPIE deve implementar um programa de treinamento que contemple, no mínimo, 3% (três por cento) da carga horária total de homem-hora trabalhada por seus profissionais (responsável, inspetores de equipamentos e PLH) nos últimos doze meses, sendo que ao menos 70% (setenta por cento) dessa carga deve ser dedicada a treinamentos de natureza técnica, gestão, legislação de segurança (NR), administrativa e outras atividades de suporte, todas relacionadas com as atividades de inspeção de equipamentos."}, {"c": "dou-paragraph", "t": "5.1.3.8.1 Para fins de contabilização da carga horária técnica, poderão ser incluídas:"}, {"c": "dou-paragraph", "t": "a) a participação em eventos técnicos formais, como congressos, workshops e seminários;"}, {"c": "dou-paragraph", "t": "b) a docência em cursos técnicos específicos de inspeção; e"}, {"c": "dou-paragraph", "t": "c) a participação em paradas programadas de manutenção de outros estabelecimentos e em auditorias internas de SPIE."}, {"c": "dou-paragraph", "t": "5.1.3.9 A contratação de mão de obra ou serviços deve restringir-se à períodos de pico de serviço, serviços eventuais ou serviços especializados. Os seguintes serviços podem ser contratados pelo SPIE:"}, {"c": "dou-paragraph", "t": "a) inspeção de equipamentos durante paradas (incluindo, quando aplicável, pré e pós-paradas) de unidades;"}, {"c": "dou-paragraph", "t": "b) inspeção de equipamentos de grande porte ou sistemas de tubulações de grande porte, desde que haja evidência formal da quantidade de mão de obra contratada, do período de execução e do tipo de atividade desenvolvida;"}, {"c": "dou-paragraph", "t": "c) execução de abrangência de acidentes ou incidentes ocorridos com itens controlados, sendo obrigatória a participação de ao menos um representante do SPIE;"}, {"c": "dou-paragraph", "t": "d) serviços especializados de engenharia, incluindo consultorias, para atender necessidades do SPIE com entregáveis rastreáveis (relatório/parecer/cálculos) validados por PLH do SPIE, sem redução do efetivo mínimo e sem transferência de responsabilidades do SPIE;"}, {"c": "dou-paragraph", "t": "e) ensaios mecânicos, metalográficos, inspeção de soldagem e ensaios não destrutivos;"}, {"c": "dou-paragraph", "t": "f) inspeção de recebimento ou fabricação;"}, {"c": "dou-paragraph", "t": "g) inspeção com acesso por corda;"}, {"c": "dou-paragraph", "t": "h) serviço de atualização de banco de dados de inspeção, organização e ajuste de arquivos ou correlatos;"}, {"c": "dou-paragraph", "t": "i) inspeção em faixas de domínio de dutos e em trechos de difícil acesso de linhas de surgência ou injeção de poços de produção de petróleo;"}, {"c": "dou-paragraph", "t": "j) manutenção, calibração e teste de válvulas de segurança;"}, {"c": "dou-paragraph", "t": "k) inspeção de controle de qualidade de reparos, de soldagem, pintura, refratário e isolamento térmico em serviços de manutenção, construção e montagem;"}, {"c": "dou-paragraph", "t": "l) inspeção de equipamentos submarinos; e"}, {"c": "dou-paragraph", "t": "m) inspeção de dutos submarinos."}, {"c": "dou-paragraph", "t": "5.1.3.10 A mão de obra contratada para ensaios não destrutivos e para outros serviços de caráter eventual deve ser selecionada e avaliada segundo critérios semelhantes aos utilizados para a mão de obra própria."}, {"c": "dou-paragraph", "t": "5.1.3.11 Para o exercício das funções de inspetor de ensaios não destrutivos, inspetor de soldagem e inspetor de pintura, devem ser exigidas as respectivas qualificações e certificações:"}, {"c": "dou-paragraph", "t": "a) inspetor de ensaios não destrutivos: conforme requisitos da norma ABNT NBR NM ISO 9712;"}, {"c": "dou-paragraph", "t": "b) inspetor de soldagem: conforme requisitos da norma ABNT NBR 14842; e"}, {"c": "dou-paragraph", "t": "c) inspetor de pintura: conforme requisitos da norma ABNT NBR 15218."}, {"c": "dou-paragraph", "t": "5.1.3.12 Para a realização de Ensaios Não Destrutivos (END) não abrangidos por normas nacionais, deve ser exigida qualificação internacional do profissional ou comprovação de capacitação formal fornecida pelo fabricante ou detentor da tecnologia utilizada, sempre que aplicável."}, {"c": "dou-paragraph", "t": "6. FUNÇÃO DO SPIE"}, {"c": "dou-paragraph", "t": "O SPIE deve acompanhar e registrar as condições físicas dos equipamentos sob seu controle, visando, através da gestão de integridade, obter e manter as condições seguras de operação. Para tanto, o SPIE deve demonstrar, através de evidências objetivas, que todos os itens sob seu controle estão incluídos em seu programa de inspeção e estão sendo devidamente acompanhados. O SPIE deve ainda garantir:"}, {"c": "dou-paragraph", "t": "a) a agilidade de suas intervenções, em qualquer situação; e"}, {"c": "dou-paragraph", "t": "b) a integração de seus princípios de atuação com os setores de manutenção, engenharia, operação, segurança e meio ambiente do estabelecimento."}, {"c": "dou-paragraph", "t": "7. ATIVIDADES DO SPIE"}, {"c": "dou-paragraph", "t": "7.1 Atividades Mandatórias"}, {"c": "dou-paragraph", "t": "O SPIE deve desenvolver as atividades a seguir:"}, {"c": "dou-paragraph", "t": "a) manter atualizada uma lista com todos os equipamentos abrangidos pelo SPIE;"}, {"c": "dou-paragraph", "t": "b) manter atualizada a lista de equipamentos sob controle do SPIE que estejam temporariamente ou definitivamente fora de operação, incluindo os que se encontram em condição de hibernação, em situação de reserva ou com previsão de retorno à operação, conforme sistemática definida pelo estabelecimento;"}, {"c": "dou-paragraph", "t": "Nota: O estabelecimento deve possuir sistemática para equipamentos em hibernação que tenham previsão de retorno a operação, com o envolvimento do SPIE nos aspectos relacionados às avaliações realizadas antes do retorno, conforme previsto na NR-13;"}, {"c": "dou-paragraph", "t": "c) implementar um programa de inspeção, em conformidade com as exigências legais e normativas, com o objetivo de garantir que os equipamentos se mantenham em condições físicas seguras para a operação;"}, {"c": "dou-paragraph", "t": "d) certificar de que o programa de inspeção, registro de segurança e eventuais recomendações de inspeção, para os equipamentos de terceiros, cuja inspeção seja de responsabilidade destes, estejam sendo cumpridos, em conformidade com as exigências legais e normativas;"}, {"c": "dou-paragraph", "t": "e) efetuar, testemunhar ou assegurar a realização dos ensaios, medições, testes e exames necessários para avaliar as condições físicas dos itens sob seu controle, com base em procedimentos;"}, {"c": "dou-paragraph", "t": "f) comparar os resultados da inspeção com os critérios estabelecidos, decidindo sobre a condição de operação do equipamento e disponibilizar os resultados aos setores envolvidos;"}, {"c": "dou-paragraph", "t": "g) emitir parecer técnico e controlar o andamento das Recomendações de Inspeção emitidas, com registro das providências, acompanhamento de prazos e controle das eventuais reavaliações de prazo de execução, com suas justificativas técnicas;"}, {"c": "dou-paragraph", "t": "Nota 1: nos casos de reavaliação, devem ser estabelecidos, em procedimento, os critérios para revalidação das Recomendações de Inspeção e a instância responsável pela aprovação dos novos prazos;"}, {"c": "dou-paragraph", "t": "Nota 2: compete ao empregador designar os responsáveis executores e assegurar a implementação dentro dos prazos estabelecidos;"}, {"c": "dou-paragraph", "t": "h) utilizar técnicas e métodos de inspeção preditiva e ou preventiva para monitorar a deterioração dos equipamentos e, caso necessário, proceder a atualização do plano de inspeção;"}, {"c": "dou-paragraph", "t": "i) manter em arquivos, rastreáveis e atualizados, os registros das inspeções;"}, {"c": "dou-paragraph", "t": "j) determinar a vida remanescente dos equipamentos e tubulações, fornecendo subsídios para o planejamento da inspeção, operação e manutenção, demonstrando o método utilizado e a frequência de avaliação, com base em procedimento, devendo a dispensa da determinação da vida remanescente estar justificada, pelo responsável técnico, para qualquer equipamento controlado pelo SPIE;"}, {"c": "dou-paragraph", "t": "k) participar de decisões ou desenvolver estudos técnicos com o objetivo de definir se algum equipamento pode operar de forma segura em condições distintas das estabelecidas no projeto;"}, {"c": "dou-paragraph", "t": "l) efetuar, testemunhar ou assegurar a verificação das condições físicas e do desempenho dos dispositivos de segurança, com base em procedimentos;"}, {"c": "dou-paragraph", "t": "m) assegurar ou realizar os ensaios, testes e medições necessários para verificar se a qualidade dos reparos e modificações executados nos equipamentos é satisfatória;"}, {"c": "dou-paragraph", "t": "n) possuir procedimentos para as principais atividades de inspeção, incluindo, no mínimo, testes, ensaios, exames e medições que devem ser executados, os respectivos critérios de aceitação, a metodologia de gestão das informações e controle dos registros;"}, {"c": "dou-paragraph", "t": "o) divulgar entre o pessoal próprio e terceirizado os procedimentos atualizados para as atividades inerentes ao SPIE;"}, {"c": "dou-paragraph", "t": "p) definir critérios para a contratação e avaliação dos serviços ou mão-de-obra de inspeção, atendendo ao disposto nesta INI-SPIE, incluindo, nos respectivos instrumentos contratuais, os procedimentos, os requisitos e critérios técnicos previstos na legislação e normas aplicáveis;"}, {"c": "dou-paragraph", "t": "q) identificar necessidades de treinamento e implementar programas visando à capacitação e certificação de seu efetivo;"}, {"c": "dou-paragraph", "t": "r) executar, testemunhar ou assegurar, por meio de evidências documentadas, que as atividades de inspeção de fabricação, construção, montagem e recebimento de equipamentos, sobressalentes e demais materiais estejam sendo realizadas conforme especificações aplicáveis;"}, {"c": "dou-paragraph", "t": "s) participar de comissões para identificar, analisar e investigar eventos indesejados;"}, {"c": "dou-paragraph", "t": "t) manter lista atualizada da aparelhagem de inspeção, inclusive daquelas não sujeitas à calibração e assegurar condições adequadas para sua preservação e guarda;"}, {"c": "dou-paragraph", "t": "u) efetuar ou providenciar a calibração da aparelhagem de inspeção, contra padrões rastreados nacional ou internacionalmente, com registros dos resultados e data de validade da calibração. Estas exigências devem estar previstas em procedimentos internos do SPIE, devidamente documentados e aprovados, de forma a garantir sua aplicação uniforme;"}, {"c": "dou-paragraph", "t": "v) disponibilizar meios que definam claramente quais os instrumentos e qual o método alternativamente utilizado para avaliação de instrumentos não sujeitos à calibração;"}, {"c": "dou-paragraph", "t": "w) possuir procedimento para segregação da aparelhagem de inspeção e analisar a validade de resultados anteriores, quando os dispositivos forem encontrados fora dos limites de confiabilidade das medições;"}, {"c": "dou-paragraph", "t": "x) participar de comissões para identificação de causas de falhas em itens sob controle do SPIE; e"}, {"c": "dou-paragraph", "t": "y) divulgar para toda a força de trabalho, de forma compreensível, seus objetivos e metas, de modo a promover o alinhamento organizacional, o engajamento dos profissionais e o fortalecimento da cultura de segurança."}, {"c": "dou-paragraph", "t": "7.2 Atividades Não Mandatórias"}, {"c": "dou-paragraph", "t": "O SPIE pode desenvolver atividades correlatas à sua função, de caráter não mandatório, desde que estas não impactem o desenvolvimento das atividades mandatórias do SPIE, tais como:"}, {"c": "dou-paragraph", "t": "a) promover ações preventivas de orientação para a operação, quanto aos procedimentos de utilização dos equipamentos, através de instruções escritas ou treinamentos;"}, {"c": "dou-paragraph", "t": "b) sugerir melhorias nas instalações existentes, com foco em aspectos de segurança, meio ambiente e otimização de processos;"}, {"c": "dou-paragraph", "t": "c) promover ações para aumentar a confiabilidade operacional dos equipamentos e unidades;"}, {"c": "dou-paragraph", "t": "d) conduzir inspeções ocasionais em equipamentos ou itens não controlados pelo SPIE;"}, {"c": "dou-paragraph", "t": "e) acompanhar a inspeção de equipamentos em comodato, cujas inspeções sejam formalmente realizadas por terceiros;"}, {"c": "dou-paragraph", "t": "f) acompanhar a inspeção de equipamentos dinâmicos ou monitorar vibrações;"}, {"c": "dou-paragraph", "t": "g) participar do planejamento de paradas;"}, {"c": "dou-paragraph", "t": "h) participar de projetos de novas instalações e modificações de processos que envolvam equipamentos abrangidos pelo SPIE;"}, {"c": "dou-paragraph", "t": "i) participar da construção e montagem de novas unidades no estabelecimento;"}, {"c": "dou-paragraph", "t": "j) acompanhar a inspeção de equipamentos e dutos submarinos; e"}, {"c": "dou-paragraph", "t": "k) acompanhar inspeções de estruturas, primárias, secundárias e auxiliares."}, {"c": "dou-paragraph", "t": "7.3 Ampliação de prazos máximos de inspeção"}, {"c": "dou-paragraph", "t": "7.3.1 O Anexo C desta Instrução Normativa descreve os requisitos e atividades gerais que devem ser atendidos pelos estabelecimentos com SPIE que desejem ampliar os prazos máximos de inspeção de suas caldeiras com base na utilização de Sistemas Instrumentados de Segurança - SIS."}, {"c": "dou-paragraph", "t": "7.3.2 O Anexo D desta Instrução Normativa descreve os requisitos e atividades gerais que devem ser atendidos pelos estabelecimentos com SPIE que desejem determinar os prazos máximos de inspeção com base na implementação de metodologia documentada de Inspeção Baseada em Risco - IBR."}, {"c": "dou-paragraph", "t": "7.3.3 O Anexo E desta Instrução Normativa descreve os requisitos e atividades a serem seguidos por estabelecimentos com SPIE que desejem estender os prazos da inspeção periódica visual interna de Vasos de Pressão, substituindo-a pela metodologia da Inspeção Não Intrusiva - INI."}, {"c": "dou-paragraph", "t": "8. SISTEMA DE DOCUMENTAÇÃO E REGISTROS"}, {"c": "dou-paragraph", "t": "8.1 Controle de Documentos"}, {"c": "dou-paragraph", "t": "O SPIE deve ter um procedimento escrito para controle de seus documentos e registros, contendo a definição das sistemáticas de emissão, cancelamento, distribuição, disponibilização e revisão."}, {"c": "dou-paragraph", "t": "8.2 Abrangência"}, {"c": "dou-paragraph", "t": "Adicionalmente ao estabelecido em 8.1, o sistema de documentação e registro do SPIE deve abranger no mínimo:"}, {"c": "dou-paragraph", "t": "a) lista atualizada de equipamentos sob controle do SPIE, contemplando os equipamentos em operação e aqueles fora de operação temporariamente, desde que com previsão de retorno à operação;"}, {"c": "dou-paragraph", "t": "Nota: o procedimento técnico do estabelecimento para itens considerados como fora de operação deve contemplar a metodologia de isolamento do sistema, tais como: bloqueio e raqueteamento, duplo bloqueio com alívio entre as válvulas e abertura para atmosfera e prever as situações que demandem a conservação dos equipamentos que fiquem nesta condição de inatividade para garantir sua integridade, incluindo inertização, bloqueio e/ou isolamento."}, {"c": "dou-paragraph", "t": "b) programa de inspeção dos itens controlados;"}, {"c": "dou-paragraph", "t": "c) programa de calibração e certificados de calibração da aparelhagem de inspeção;"}, {"c": "dou-paragraph", "t": "d) procedimentos para as principais atividades de inspeção;"}, {"c": "dou-paragraph", "t": "e) procedimentos para tratamento de reclamações e registros resultantes;"}, {"c": "dou-paragraph", "t": "f) procedimentos para tratamento de desvios, auditorias internas, avaliação de serviços contratados, conservação e segregação de aparelhagem de inspeção;"}, {"c": "dou-paragraph", "t": "g) dados técnicos de projeto e fabricação dos equipamentos, tubulações e dispositivos de segurança;"}, {"c": "dou-paragraph", "t": "h) informações detalhadas, conforme previsto pela ABNT NBR 16455, referentes aos processos de Inspeção Não Intrusiva realizados pelo SPIE, quando aplicável;"}, {"c": "dou-paragraph", "t": "i) informações referentes ao processo de SIS das caldeiras, conforme previsto pela ABNT NBR IEC 61511-1, quando aplicável;"}, {"c": "dou-paragraph", "t": "j) informações detalhadas sobre o processo de Inspeção Baseada em Risco (IBR), quando aplicável;"}, {"c": "dou-paragraph", "t": "k) certificados de fabricação e montagem dos itens controlados;"}, {"c": "dou-paragraph", "t": "l) registros das inspeções com os respectivos resultados, medições, análises de vida residual e cálculos especializados;"}, {"c": "dou-paragraph", "t": "m) recomendações decorrentes das inspeções;"}, {"c": "dou-paragraph", "t": "n) projetos de alteração ou reparo, quando aplicáveis;"}, {"c": "dou-paragraph", "t": "o) documentos atualizados dos profissionais próprios ou contratados, contendo escolaridade, qualificação, habilitação e a respectiva certificação, quando aplicável;"}, {"c": "dou-paragraph", "t": "p) contratos com empresas terceirizadas que executem atividades de inspeção sob responsabilidade direta do SPIE;"}, {"c": "dou-paragraph", "t": "q) documentação que subsidie eventuais alterações introduzidas no SPIE (rastreabilidade de alterações);"}, {"c": "dou-paragraph", "t": "r) pareceres técnicos e laudos emitidos pelos PLH do SPIE ou por ele contratados; e"}, {"c": "dou-paragraph", "t": "s) critérios e cálculos para definição do efetivo mínimo do SPIE."}, {"c": "dou-paragraph", "t": "8.3 Registros da Qualidade"}, {"c": "dou-paragraph", "t": "Os registros da qualidade que subsidiam as auditorias de SPIE devem ser:"}, {"c": "dou-paragraph", "t": "a) indeléveis, de modo a preservar a integridade do processo;"}, {"c": "dou-paragraph", "t": "b) suficientemente claros;"}, {"c": "dou-paragraph", "t": "c) identificados e adequadamente dispostos de forma a assegurar sua rastreabilidade; e"}, {"c": "dou-paragraph", "t": "d) mantidos por, no mínimo, período exigido pelas obrigações contratuais, legais e normativas, o que for maior."}, {"c": "dou-paragraph", "t": "8.4 Registros assinados por Profissional Legalmente Habilitado"}, {"c": "dou-paragraph", "t": "8.4.1 Os seguintes registros devem ser assinados por Profissional Legalmente Habilitado e atender aos demais critérios estabelecidos na Norma Regulamentadora NR-13, quando aplicável:"}, {"c": "dou-paragraph", "t": "a) todos os relatórios de inspeção, recomendações de inspeção, reavaliações de prazos de recomendações de inspeção e projetos de alteração ou reparo, excetuando-se aqueles onde a NR-13 permite aprovação por Responsável Técnico;"}, {"c": "dou-paragraph", "t": "b) reconstituições de prontuários de equipamentos dentro do escopo da Norma Regulamentadora NR-13;"}, {"c": "dou-paragraph", "t": "c) justificativa formal para postergação de inspeções;"}, {"c": "dou-paragraph", "t": "d) justificativa técnica para utilização de tecnologias de cálculo ou procedimentos distintos daqueles previstos pelos códigos de projeto;"}, {"c": "dou-paragraph", "t": "e) justificativa técnica para substituição de exame visual interno ou externo por impossibilidade física de acesso, com uso de exames não destrutivos ou outras metodologias de avaliação da integridade;"}, {"c": "dou-paragraph", "t": "f) análise técnica atestando a integridade dos equipamentos, tubulações e dispositivos de segurança com inspeção em atraso;"}, {"c": "dou-paragraph", "t": "Nota: Quando se tratar de dispositivos de segurança, a análise deve considerar histórico operacional e avaliação de risco;"}, {"c": "dou-paragraph", "t": "g) documentos que subsidiem a neutralização provisória dos instrumentos e controles;"}, {"c": "dou-paragraph", "t": "h) relatórios e estudos relacionados à aplicação da metodologia de Inspeção Baseada em Risco (IBR);"}, {"c": "dou-paragraph", "t": "i) relatórios e estudos para execução de Inspeção Não Intrusiva (INI); e"}, {"c": "dou-paragraph", "t": "j) parecer técnico fundamentando a decisão de extensão de prazo de caldeiras com Sistema Instrumentado de Segurança (SIS)."}, {"c": "dou-paragraph", "t": "8.4.2 O relatório de inspeção consolidado, contendo a análise técnica e as recomendações finais, deve ser assinado por Profissional Legalmente Habilitado (PLH), ou, quando expressamente admitido pela NR-13, pelo Responsável Técnico."}, {"c": "dou-paragraph", "t": "8.4.3 Os relatórios técnicos ou laudos de Ensaios Não Destrutivos (END) realizados por empresas contratadas devem compor os anexos do relatório principal, desde que estejam referenciados e tecnicamente validados pelo PLH responsável."}, {"c": "dou-paragraph", "t": "9. CONTRATAÇÃO DE SERVIÇOS"}, {"c": "dou-paragraph", "t": "9.1 O SPIE deve estabelecer critérios técnicos para a contratação dos serviços de inspeção e deve verificar se todo o pessoal envolvido na contratação atende às exigências de qualificação e certificação mencionadas nesta Instrução Normativa."}, {"c": "dou-paragraph", "t": "9.2 O SPIE deve manter registro do pessoal contratado, identificando o contrato, tipo de atividade desenvolvida, período da contratação, qualificações e certificações. O SPIE deve possuir critérios documentados para avaliação de desempenho dos serviços contratados e manter os registros das avaliações realizadas."}, {"c": "dou-paragraph", "t": "10. CONTROLE DA APARELHAGEM DE INSPEÇÃO"}, {"c": "dou-paragraph", "t": "10.1 O SPIE deve manter uma lista atualizada de sua aparelhagem de inspeção, inclusive daqueles não sujeitos à calibração."}, {"c": "dou-paragraph", "t": "10.2 O SPIE deve possuir registros das calibrações realizadas."}, {"c": "dou-paragraph", "t": "10.3 O SPIE deve possuir procedimentos definindo o controle, a periodicidade de calibração e a preservação da aparelhagem de inspeção."}, {"c": "dou-paragraph", "t": "10.4 O SPIE deve analisar os resultados produzidos pela aparelhagem de inspeção, durante o seu uso, e atestar a sua validade. Quando os resultados não mostrarem confiabilidade, ou houver dúvida, o instrumento utilizado deve ser segregado, conforme procedimento específico, e as ações necessárias devem ser definidas."}, {"c": "dou-paragraph", "t": "10.5 A calibração desta aparelhagem deve ser feita contra padrões nacional ou internacionalmente reconhecidos. Quando não existirem estes padrões, a base utilizada para esta calibração deve ser documentada e revisada periodicamente."}, {"c": "dou-paragraph", "t": "11. AUDITORIAS INTERNAS"}, {"c": "dou-paragraph", "t": "11.1 O SPIE deve realizar auditorias internas, conforme programação e procedimento existente."}, {"c": "dou-paragraph", "t": "11.2 O procedimento de auditoria interna deve conter no mínimo:"}, {"c": "dou-paragraph", "t": "a) qualificação, experiência e isenção dos profissionais envolvidos;"}, {"c": "dou-paragraph", "t": "b) abrangência e periodicidade das auditorias;"}, {"c": "dou-paragraph", "t": "c) lista de requisitos aplicáveis; e"}, {"c": "dou-paragraph", "t": "d) metodologia de registro de não conformidades, preocupações e observações."}, {"c": "dou-paragraph", "t": "11.3 A CIPA e, quando houver, a representação sindical da categoria profissional predominante no estabelecimento, devem ser convidadas a participar das entrevistas e das reuniões de abertura e encerramento."}, {"c": "dou-paragraph", "t": "12. NÃO CONFORMIDADES (NC) E AÇÕES CORRETIVAS"}, {"c": "dou-paragraph", "t": "12.1 O SPIE deve possuir procedimento escrito para tratamento das NC e preocupações evidenciadas nas auditorias internas ou externas."}, {"c": "dou-paragraph", "t": "12.2 Para cada não conformidade ou preocupação devem ser definidas:"}, {"c": "dou-paragraph", "t": "a) identificação e descrição da não conformidade ou preocupação;"}, {"c": "dou-paragraph", "t": "b) determinação das causas da não conformidade ou preocupação;"}, {"c": "dou-paragraph", "t": "c) implementação de ações de correção dos desvios que levaram à aplicação da NC ou preocupação;"}, {"c": "dou-paragraph", "t": "d) definição de ações corretivas para evitar a repetição da NC ou a evolução da preocupação para NC, prevendo ações de abrangência, quando necessário;"}, {"c": "dou-paragraph", "t": "e) implementação das ações corretivas em tempo hábil;"}, {"c": "dou-paragraph", "t": "f) análise da eficácia das ações corretivas; e"}, {"c": "dou-paragraph", "t": "g) registros das informações acima descritas."}, {"c": "dou-paragraph", "t": "13. ANÁLISE CRÍTICA"}, {"c": "dou-paragraph", "t": "13.1 A análise crítica dos resultados do SPIE deve ser periódica, com registro formal abrangendo pelo menos as deliberações referentes aos seguintes assuntos:"}, {"c": "dou-paragraph", "t": "a) acompanhamento dos indicadores do SPIE, incluindo necessariamente o atendimento da programação de inspeção e o controle das recomendações de inspeção;"}, {"c": "dou-paragraph", "t": "b) análise dos resultados de auditorias internas e externas do SPIE;"}, {"c": "dou-paragraph", "t": "c) acompanhamento do tratamento e do andamento das ações corretivas de não conformidades (NC) e preocupações evidenciadas nas auditorias internas ou externas;"}, {"c": "dou-paragraph", "t": "d) acompanhamento das reclamações recebidas pelo SPIE; e"}, {"c": "dou-paragraph", "t": "e) parecer da alta administração sobre os resultados apresentados, bem como decisões sobre ações de melhoria a serem implementadas estabelecendo prazos e responsáveis por sua execução."}, {"c": "dou-paragraph", "t": "14. RECLAMAÇÕES"}, {"c": "dou-paragraph", "t": "14.1 O SPIE deve possuir procedimento para tratamento de todas as reclamações relativas aos seus serviços."}, {"c": "dou-paragraph", "t": "14.2 O procedimento deve abranger clientes internos e externos, quando aplicável."}, {"c": "dou-paragraph", "t": "14.3 O SPIE deve divulgar para toda a força de trabalho e público externo o canal ou outros meios para registro das reclamações."}, {"c": "dou-paragraph", "t": "14.4 O SPIE deve manter registros das reclamações recebidas contendo pelo menos:"}, {"c": "dou-paragraph", "t": "a) registro do recebimento da reclamação;"}, {"c": "dou-paragraph", "t": "b) evidências de que foi dado retorno ao reclamante sobre o recebimento da reclamação;"}, {"c": "dou-paragraph", "t": "c) identificação do responsável pela coleta de informações necessárias para análise e tratamento da reclamação;"}, {"c": "dou-paragraph", "t": "d) registros do tratamento das reclamações por profissionais que não tenham vínculo com o assunto da reclamação;"}, {"c": "dou-paragraph", "t": "e) registro formal de retorno ao reclamante ao final do processo; e"}, {"c": "dou-paragraph", "t": "f) registro das ações necessárias para solucionar a reclamação."}, {"c": "dou-paragraph", "t": "ANEXO A - CRITÉRIOS PARA A DETERMINAÇÃO DE EFETIVO MÍNIMO DO SPI"}, {"c": "dou-paragraph", "t": "1. CLASSIFICAÇÃO DAS INSTALAÇÕES"}, {"c": "dou-paragraph", "t": "Em função das particularidades de cada tipo de instalação e das atividades nelas desenvolvidas, as instalações controladas pelo SPIE são classificadas em 3 (três) grupos, conforme descrição a seguir:"}, {"c": "dou-paragraph", "t": "a) Grupo A: Instalações localizadas em terra e concentradas num mesmo local;"}, {"c": "dou-paragraph", "t": "b) Grupo B: Instalações não concentradas e localizadas em terra;"}, {"c": "dou-paragraph", "t": "c) Grupo C: Instalações localizadas no mar."}, {"c": "dou-paragraph", "t": "Nota: Os estabelecimentos que possuírem instalações que englobem mais de um dos grupos acima descritos devem aplicar os critérios específicos para cada caso isoladamente. O efetivo mínimo será o resultado do somatório dos casos específicos."}, {"c": "dou-paragraph", "t": "2. FÓRMULAS PARAMÉTRICAS"}, {"c": "dou-paragraph", "t": "2.1 Determinação da quantidade de inspetores de equipamentos:"}, {"c": "dou-paragraph", "t": "Onde:"}, {"c": "dou-paragraph", "t": "I = quantidade mínima de inspetores de equipamentos."}, {"c": "dou-paragraph", "t": "Fi = 1,36. Este fator corresponde à soma de fatores relativos a tarefas não diretamente relacionadas com a inspeção de equipamentos, mas que interferem diretamente no desenvolvimento dos inspetores, ou da própria atividade, acarretando acréscimo da quantidade de HH calculada, conforme indicada em HHiq. Tais fatores, expressos em pontos percentuais, são:"}, {"c": "dou-paragraph", "t": "a) 3% (três por cento) para treinamento;"}, {"c": "dou-paragraph", "t": "b) 10% (dez por cento) para estudos técnicos;"}, {"c": "dou-paragraph", "t": "c) 2% (dois por cento) para atividades de compra, recebimento, preservação e calibração da aparelhagem de inspeção;"}, {"c": "dou-paragraph", "t": "d) 16% (dezesseis por cento) para inspeções externas de rotina nas unidades, preparativos etc.; e"}, {"c": "dou-paragraph", "t": "e) 5% (cinco por cento) para atividades de apoio técnico e recebimento de materiais à área de suprimento."}, {"c": "dou-paragraph", "t": "Fti = 0,20. Este fator considera a quantidade de HH de inspetores de equipamentos necessária para executar as atividades de inspeção das tubulações da área externa e dutos, como uma porcentagem de 20% (vinte por cento) do total de HH dos inspetores de equipamentos para os demais ativos. Caso os equipamentos do SPIE não possuam tubulações externas ou dutos, o Fator Fti poderá ser considerado igual a zero."}, {"c": "dou-paragraph", "t": "Ft = 0,45. Este fator representa o esforço de inspeção sobre tubulações em ambientes industriais devendo ser considerado uma porcentagem de 45% (quarenta e cinco por cento) do total de HH dos inspetores de equipamentos."}, {"c": "dou-paragraph", "t": "T = quantidade de horas normais trabalhadas por ano, por um inspetor de equipamentos. Este fator deve levar em conta o mês de férias, fins de semana, feriados, licenças etc. e, quando aplicável, considerar regimes especiais de trabalho, considerando-se os seguintes valores de referência:"}, {"c": "dou-paragraph", "t": "T = 1.760 h para as instalações dos Grupos A e B;"}, {"c": "dou-paragraph", "t": "T = 1.584 h para instalações do Grupo C."}, {"c": "dou-paragraph", "t": "Nota: Em instalações onde engenheiros e técnicos atuem sob regimes distintos (como em offshore, com técnicos embarcados e engenheiros em terra), o valor de T pode ser diferenciado conforme regime de trabalho, desde que justificado."}, {"c": "dou-paragraph", "t": "HHiq = quantidade total de horas de inspetores de equipamentos consumidas por ano, para os equipamentos do tipo \"q\", expressa em HH/ano e calculada da seguinte forma:"}, {"c": "dou-paragraph", "t": "Onde:"}, {"c": "dou-paragraph", "t": "q = tipo de equipamento, conforme Tabela 1 deste Anexo;"}, {"c": "dou-paragraph", "t": "Qq = quantidade de equipamentos distribuídos pelos tipos \"q\", conforme Tabela 1 deste Anexo;"}, {"c": "dou-paragraph", "t": "Tiq = tempos médios, em horas, despendidos por um inspetor de equipamentos, para executar todas as etapas da inspeção de um equipamento do tipo \"q\", conforme Tabela 1 deste Anexo;"}, {"c": "dou-paragraph", "t": "liq = intervalos médios, em anos, para a inspeção de equipamentos do tipo \"q\", conforme Tabela 1 deste Anexo."}, {"c": "dou-paragraph", "t": "2.2 Determinação da quantidade de engenheiros e PLH:"}, {"c": "dou-paragraph", "t": "Onde:"}, {"c": "dou-paragraph", "t": "E = quantidade mínima de engenheiros;"}, {"c": "dou-paragraph", "t": "Fe = 2,70. Este fator corresponde à soma de fatores, relativos a tarefas não diretamente relacionadas com a atividade de engenharia de inspeção de equipamentos, mas que interferem diretamente no desenvolvimento dos engenheiros, ou da própria atividade, acarretando acréscimo da quantidade de HH calculada, conforme indicada em HHeq. Tais fatores, expressos em pontos percentuais, são:"}, {"c": "dou-paragraph", "t": "a) 5% (cinco por cento) para treinamento;"}, {"c": "dou-paragraph", "t": "b) 100% (cem por cento) para estudos técnicos de causas de deterioração e extensão de vida útil, participação em grupos técnicos, elaboração de procedimentos, contatos externos, reuniões, elaboração de relatórios etc.;"}, {"c": "dou-paragraph", "t": "c) 2% (dois por cento) para compra, recebimento e preservação de materiais para inspeção de equipamentos;"}, {"c": "dou-paragraph", "t": "d) 50% (cinquenta por cento) para atividades de supervisão, planejamento e programação; e"}, {"c": "dou-paragraph", "t": "e) 13% (treze por cento) para inspeção externa de rotina nas unidades, preparativos etc."}, {"c": "dou-paragraph", "t": "Fte = 0,10. Este fator considera a quantidade de HH de engenheiros necessários para executar as atividades de inspeção das tubulações da área externa e dutos, considerado como 10% (dez por cento) do total de HH destes profissionais necessários para todos os demais equipamentos."}, {"c": "dou-paragraph", "t": "Nota 1: Em instalações onde tais atividades demandem esforço superior, este fator deverá ser ajustado para mais."}, {"c": "dou-paragraph", "t": "Nota 2: Caso o SPIE não possua tubulações externas e dutos, ou não for aplicável, o Fator Fte deverá ser considerado igual a zero mediante apresentação de justificativa técnica."}, {"c": "dou-paragraph", "t": "Ft = 0,45. Este fator considera a quantidade de HH de engenheiros, necessários para executar as atividades de inspeção de tubulações da área interna."}, {"c": "dou-paragraph", "t": "T = quantidade de horas normais trabalhadas por ano, por um engenheiro. Este fator deve levar em conta o mês de férias, fins de semana, feriados, licenças etc. e, quando aplicável, considerar regimes especiais de trabalho, considerando-se os seguintes valores de referência:"}, {"c": "dou-paragraph", "t": "T = 1.760 h para as instalações dos Grupos A e B;"}, {"c": "dou-paragraph", "t": "T = 1.584 h para instalações do Grupo C."}, {"c": "dou-paragraph", "t": "Nota 1: O fator de 5% (por cento) relativo a treinamento na fórmula de dimensionamento de engenheiros representa uma estimativa média de consumo de carga horária para esta atividade, e não deve ser interpretado como exigência mínima. A obrigatoriedade mínima de 3% (três por cento) de treinamento técnico anual encontra-se estabelecida no item 5.1.3.6."}, {"c": "dou-paragraph", "t": "Nota 2: Nos casos em que profissionais vinculados à mesma instalação atuem em regimes distintos (ex: engenheiros em terra e técnicos embarcados), o fator T pode ser diferenciado, desde que tecnicamente justificado e formalmente documentado pelo SPIE."}, {"c": "dou-paragraph", "t": "HHeq = quantidade total de horas de engenheiros consumidas por ano, para os equipamentos do tipo \"q\", expressa em HH/ano e calculada da seguinte forma:"}, {"c": "dou-paragraph", "t": "Onde:"}, {"c": "dou-paragraph", "t": "q = tipo de equipamento, conforme Tabela 1 deste Anexo;"}, {"c": "dou-paragraph", "t": "Qq = quantidade de equipamentos distribuídos pelos tipos \"q\", conforme Tabela 1 deste Anexo;"}, {"c": "dou-paragraph", "t": "T eq = tempos médios, em horas, despendidos por um engenheiro, para realizar as atividades de engenharia de inspeção, em um equipamento do tipo \"q\", conforme Tabela 1 deste Anexo;"}, {"c": "dou-paragraph", "t": "I iq = intervalos médios, em anos, para a inspeção de equipamentos do tipo \"q\", conforme Tabela 1 deste Anexo."}, {"c": "dou-paragraph", "t": "3. TABELA PARA DETERMINAÇÃO DO EFETIVO MÍNIMO"}, {"c": "dou-paragraph", "t": "3.1 A Tabela 1 apresenta os tipos de equipamentos normalmente encontrados em instalações industriais, os tempos médios de inspeção despendidos pelos inspetores de equipamentos e pelos PLH e os intervalos médios de inspeção dos equipamentos."}, {"c": "dou-paragraph", "t": "3.2 Para estabelecimentos que possuam outros tipos de equipamentos ou uma distribuição desproporcional de determinados tipos de equipamentos, tubulações ou dutos, pode ser necessário adotar outros critérios diferenciados, justificados tecnicamente."}, {"c": "dou-paragraph", "t": "3.3 As empresas que possuírem instalações que englobem mais de um dos grupos descritos no item 1 deste Anexo devem aplicar os critérios específicos para cada caso isoladamente. O efetivo mínimo do SPIE será o resultado do somatório de cada caso específico."}, {"c": "dou-paragraph", "t": "Legenda:"}, {"c": "dou-paragraph", "t": "a) equipamentos distintos dos discriminados da Tabela, sob responsabilidade do SPIE, devem ser discriminados em linhas adicionais;"}, {"c": "dou-paragraph", "t": "b) quando algum tipo de equipamento não estiver sobre responsabilidade do SPIE, considerar Qq=0;"}, {"c": "dou-paragraph", "t": "Nota 1: Devem ser considerados todos os equipamentos sob responsabilidade do SPIE;"}, {"c": "dou-paragraph", "t": "Nota 2: Para geradores de vapor com pressão superior a 20 kgf/cm², recomenda-se ajuste dos HH conforme complexidade e criticidade, justificado tecnicamente."}, {"c": "dou-paragraph", "t": "c) para estabelecimentos com unidades operacionais distintas, deve ser avaliado o número mínimo de profissionais por unidade, de modo a assegurar cobertura técnica local adequada, compatível com a criticidade e o volume de equipamentos;"}, {"c": "dou-paragraph", "t": "d) para os cálculos devem ser considerados os valores até a primeira casa decimal."}, {"c": "dou-paragraph", "t": "4. CORREÇÃO DO EFETIVO EM FUNÇÃO DO DESLOCAMENTO"}, {"c": "dou-paragraph", "t": "4.1 Para estabelecimentos com instalações do Grupo B, a quantidade de inspetores e engenheiros calculada conforme a Tabela 1 deve ser corrigida pelo fator de deslocamento, como descrito a seguir:"}, {"c": "dou-paragraph", "t": "[Fator de Deslocamento = Fator de Distância x Fator de Facilidade de Deslocamento]"}, {"c": "dou-paragraph", "t": "4.2 O Fator de Distância deve ser calculado em relação à base onde estão sediados os engenheiros e inspetores de equipamentos e seus valores estão apresentados na Tabela 2."}, {"c": "dou-paragraph", "t": "4.3 O Fator de Facilidade de Deslocamento é determinado pelas condições das vias de acesso aos equipamentos e instalações e seus valores estão apresentados na Tabela 3."}, {"c": "dou-paragraph", "t": "Tabela 3. Determinação do Fator de Facilidade de Deslocamento"}, {"c": "", "t": "Condições de Deslocamento"}, {"c": "", "t": "Fator de Facilidade de Deslocamento"}, {"c": "", "t": "Precário"}, {"c": "", "t": "1,50"}, {"c": "", "t": "Regular"}, {"c": "", "t": "1,25"}, {"c": "", "t": "Bom"}, {"c": "", "t": "1,00"}, {"c": "dou-paragraph", "t": "5. FATORES A SEREM CONSIDERADOS NO DIMENSIONAMENTO DO EFETIVO MÍNIMO"}, {"c": "dou-paragraph", "t": "5.1 A Tabela 1 deste Anexo apresenta os tipos de equipamentos, normalmente encontrados em instalações industriais, os tempos médios de inspeção despendidos pelos inspetores de equipamentos e pelos engenheiros e os intervalos médios de inspeção dos equipamentos. A determinação do efetivo mínimo do SPIE deve considerar a quantidade de profissionais obtida pelos cálculos descritos nesta Tabela."}, {"c": "dou-paragraph", "t": "5.1.1 Os valores obtidos, quando fracionados, devem ser arredondados para o número inteiro imediatamente superior."}, {"c": "dou-paragraph", "t": "5.1.2 Em unidades offshore ou de operação contínua, o efetivo mínimo obtido deve considerar o regime de trabalho do SPIE."}, {"c": "dou-paragraph", "t": "5.1.3 Unidades industriais com idade de operação superior ao projeto original e com histórico de falhas devem ajustar o efetivo calculado do SPIE em mais de 10% (dez por cento), considerando o aumento de atividades correlatas à inspeção e de análise de falhas."}, {"c": "dou-paragraph", "t": "5.2 A quantidade calculada obtida para dimensionamento de efetivo, também deve ser ajustada em 10% (dez por cento) para cima, caso sejam constatados um ou mais dos fatores citados a seguir:"}, {"c": "dou-paragraph", "t": "a) quando o total de horas extras anuais do pessoal próprio ultrapassar 10% (dez por cento) do total de horas-homem (HH) disponíveis no período, de forma recorrente e não associada exclusivamente a picos sazonais de serviço; e"}, {"c": "dou-paragraph", "t": "b) quando houver acúmulo ou atraso de serviços superiores a 10% (dez por cento) das inspeções previstas no plano anual ou dos prazos máximos de atendimento definidos na sistemática interna do SPIE, em dois anos consecutivos."}, {"c": "dou-paragraph", "t": "5.3 Na hipótese de não ocorrência de nenhum dos fatores elencados no item 5.2, pode ser admitida, mediante justificativa técnica formal, uma redução no efetivo mínimo calculado de até 20% (vinte por cento), desde que seja comprovadamente atendido pelo menos um dos seguintes critérios:"}, {"c": "dou-paragraph", "t": "a) as instalações industriais apresentem, de forma comprovada:"}, {"c": "dou-paragraph", "t": "a.1) histórico consolidado de baixa incidência de falhas e ocorrências em itens controlados pelo SPIE;"}, {"c": "dou-paragraph", "t": "a.2) predominância de equipamentos e processos de baixa criticidade, incluindo uso extensivo de materiais resistentes à corrosão ou autolimpantes;"}, {"c": "dou-paragraph", "t": "a.3) predominância de equipamentos criogênicos ou sistemas com fluidos de baixa agressividade;"}, {"c": "dou-paragraph", "t": "a.4) utilização de layouts industriais com baixo grau de confinamento ou complexidade operacional;"}, {"c": "dou-paragraph", "t": "b) o estabelecimento demonstre a adoção eficaz de tecnologias e metodologias que aumentem significativamente a precisão e a efetividade da atividade de inspeção, tais como:"}, {"c": "dou-paragraph", "t": "b.1) sistemas instrumentados de segurança de processo (SIS) validados;"}, {"c": "dou-paragraph", "t": "b.2) monitoramento contínuo de integridade de ativos por sensores online ou tecnologia equivalente; ou"}, {"c": "dou-paragraph", "t": "b.3) aplicação sistemática de metodologias formalizadas de inspeção baseada em risco (IBR) ou inspeção não intrusiva (INI), conforme previsto na NR-13 e nas normas técnicas nacionais e internacionais vigentes."}, {"c": "dou-paragraph", "t": "5.3.1 A aplicação da redução mencionada neste item deverá ser registrada formalmente na documentação do SPIE, estar lastreada em evidências documentais auditáveis, e será reavaliada a cada ciclo de auditoria."}, {"c": "dou-paragraph", "t": "5.4 Caso seja constatada a repetição de atrasos na execução do plano de inspeção em auditorias subsequentes, independentemente de se tratar ou não do mesmo equipamento, a bonificação prevista no item 5.3 será cancelada, devendo o efetivo mínimo ser recalculado conforme a fórmula paramétrica da Tabela 1."}, {"c": "dou-paragraph", "t": "5.5 Para os estabelecimentos que demandam esforços recorrentes de reavaliação de recomendações de inspeção (RI), deve ser aplicado Fator de Correção (FRI). Este fator de Correção de quadro próprio - FRI, para gestão de Recomendações de Inspeção, deve ser considerado e aplicado para o identificado para Inspetores de Equipamentos na Tabela 1, de acordo com a fórmula:"}, {"c": "dou-paragraph", "t": "\"Efetivo Mínimo Corrigido = Efetivo Mínimo x (1+FRI)\", sendo:"}, {"c": "dou-paragraph", "t": "Tabela 4 - Fator de Correção de Quadro Próprio (FRI)"}, {"c": "", "t": "Grupo doEstabelecimento"}, {"c": "", "t": "Relação \"R\"Ver nota de rodapé"}, {"c": "", "t": "Valor de FRI"}, {"c": "", "t": "A"}, {"c": "", "t": "Menor do que 10"}, {"c": "", "t": "0"}, {"c": "", "t": "Entre 10 e 12"}, {"c": "", "t": "0,075"}, {"c": "", "t": "Maior ou igual a 12"}, {"c": "", "t": "0,15"}, {"c": "", "t": "B ou C"}, {"c": "", "t": "Menor do que 4"}, {"c": "", "t": "0"}, {"c": "", "t": "Entre 4 e 4,8"}, {"c": "", "t": "0,075"}, {"c": "", "t": "Maior ou igual a 12"}, {"c": "", "t": "0,15"}, {"c": "dou-paragraph", "t": "Nota: R= Tub / Equip Est"}, {"c": "dou-paragraph", "t": "Tub = quantitativo de itens individuais controlados de tubulação da Lista de Linhas do SPIE, contidas nos Sistemas de Tubulações."}, {"c": "dou-paragraph", "t": "Equip Est = quantitativo de Equipamentos Estáticos controlados pelo SPIE (quantificados na Tabela 1 do Anexo A)"}, {"c": "dou-paragraph", "t": "ANEXO B - FORMAÇÃO E CAPACITAÇÃO DE INSPETORES DE EQUIPAMENTOS"}, {"c": "dou-paragraph", "t": "1.OBJETIVO"}, {"c": "dou-paragraph", "t": "Este Anexo estabelece requisitos para a formação e capacitação de Inspetores de Equipamentos que desenvolvem atividades em Serviços Próprios de Inspeção de Equipamentos - SPIE."}, {"c": "dou-paragraph", "t": "2. PRÉ-REQUISITOS"}, {"c": "dou-paragraph", "t": "2.1 O candidato a inspetor de equipamentos deve estar apto para atender os critérios de saúde ocupacional definidos pelo estabelecimento."}, {"c": "dou-paragraph", "t": "2.2 O candidato a inspetor de equipamentos deve comprovar, no mínimo, formação técnica de nível médio, reconhecida pelo respectivo Conselho de Classe."}, {"c": "dou-paragraph", "t": "2.2.1 Para comprovação de escolaridade será exigida a apresentação de cópia do diploma ou certificado de conclusão de curso fornecido por entidade reconhecida oficialmente."}, {"c": "dou-paragraph", "t": "3. CAPACITAÇÃO"}, {"c": "dou-paragraph", "t": "3.1 Para efeito desta INI-SPIE, deve ser considerado como inspetor de equipamentos aquele profissional que satisfizer uma das condições apresentadas a seguir:"}, {"c": "dou-paragraph", "t": "a) possuir comprovação formal que atuava como inspetor de equipamentos em operação antes de fevereiro de 2001; e/ou"}, {"c": "dou-paragraph", "t": "b) atender aos pré-requisitos estabelecidos neste Anexo e for aprovado em curso de formação."}, {"c": "dou-paragraph", "t": "4. CURSO DE FORMAÇÃO DE INSPETOR DE EQUIPAMENTOS"}, {"c": "dou-paragraph", "t": "4.1 O curso de formação de inspetor de equipamentos deve ser ministrado por pessoa jurídica legalmente constituída e supervisionado tecnicamente por PLH, com conteúdo programático e carga horária mínima conforme Tabela 1 deste Anexo."}, {"c": "dou-paragraph", "t": "4.2 As cargas horárias específicas das disciplinas de cada módulo são mínimas, podendo ser ampliadas, conforme conveniências técnicas ou pedagógicas da instituição que ministrar o curso."}, {"c": "dou-paragraph", "t": "4.3 As cargas horárias mínimas previstas podem ser ampliadas conforme conveniência técnico-pedagógica da instituição reconhecida MEC, respeitando-se os conteúdos obrigatórios."}, {"c": "dou-paragraph", "t": "4.4 Cabe à Coordenação do treinamento liberar, ou não, o candidato que apresentar comprovação formal de competências adquiridas em algumas disciplinas ministradas em outros cursos reconhecidos, sendo mantida, entretanto, a obrigatoriedade das avaliações (provas)."}, {"c": "dou-paragraph", "t": "4.5 Compete ao Coordenador do Curso de Formação ou da Instituição a liberação de participação em disciplinas específicas, mediante comprovação formal de competências previamente adquiridas, sendo mantida, obrigatoriamente, a realização das respectivas avaliações."}, {"c": "dou-paragraph", "t": "4.6 Para ser aprovado no curso de formação, o candidato deve obter aproveitamento igual ou superior a 7 (sete) em cada disciplina e frequência mínima de 90% (noventa por cento)."}, {"c": "dou-paragraph", "t": "4. A certificação final do curso de inspetor de equipamentos será concedida após a conclusão de todos os módulos."}, {"c": "dou-paragraph", "t": "4.8 O diploma deve explicitar os módulos e as disciplinas cursadas, com as respectivas cargas horárias, aproveitamento e frequência, e conter o nome e assinatura do PLH responsável pela supervisão."}, {"c": "dou-paragraph", "t": "4.8.1 O curso deve contemplar uma carga horária mínima de 40 (quarenta) horas dedicadas a aulas práticas presenciais, visitas técnicas ou estágio supervisionado por PLH, abrangendo a execução de inspeções de equipamentos com base nos conhecimentos adquiridos, elaboração de laudos e emissão de relatórios técnicos conforme normas aplicáveis."}, {"c": "dou-paragraph", "t": "4.8.2 Independentemente da metodologia adotada para execução da carga horária prática, o curso de formação deve prever, no mínimo, 30% (trinta por cento) da carga total de treinamento em atividades presenciais supervisionadas, com participação física do aluno em ambiente de aprendizagem estruturado."}, {"c": "dou-paragraph", "t": "4.8.2.1 Essa exigência aplica-se inclusive nos casos em que forem adotadas simulações digitais ou recursos de realidade virtual."}, {"c": "dou-paragraph", "t": "Tabela 1 - Carga Horária mínima do Curso de Formação de Inspetores de Equipamentos"}, {"c": "", "t": "MÓDULO I"}, {"c": "", "t": "DISCIPLINA"}, {"c": "", "t": "HORAS"}, {"c": "", "t": "ConhecimentosBásicos"}, {"c": "", "t": "I.1 - Noções de Processamento Contínuo, tais como: Petróleo (Refino, E&P), Petroquímico, Químico, Papel e Celulose, Geração de Energia, Transporte dutoviário, logística, dentre outros"}, {"c": "", "t": "08"}, {"c": "", "t": "I.2 - Noções das NRs 1, 3, 5, 6, 9, 15, 20, 26, 28, 33, 35 e 37"}, {"c": "", "t": "08"}, {"c": "", "t": "I.3 - Noções de Avaliação da Conformidade"}, {"c": "", "t": "08"}, {"c": "", "t": "I.4 - Introdução à proteção ao meio ambiente"}, {"c": "", "t": "04"}, {"c": "", "t": "I.5 - Aspectos legais da Inspeção de Equipamentos"}, {"c": "", "t": "08"}, {"c": "", "t": "I.6 - Normalização Técnica"}, {"c": "", "t": "08"}, {"c": "", "t": "I.7 - Metrologia"}, {"c": "", "t": "06"}, {"c": "", "t": "I.8 - Desenho Técnico e Isométricos"}, {"c": "", "t": "08"}, {"c": "", "t": "Total do Módulo"}, {"c": "", "t": "58"}, {"c": "", "t": "MÓDULO II"}, {"c": "", "t": "DISCIPLINA"}, {"c": "", "t": "HORAS"}, {"c": "", "t": "ConhecimentosEspecíficos"}, {"c": "", "t": "II.1- Metalurgia e Seleção de Materiais"}, {"c": "", "t": "28"}, {"c": "", "t": "II.2- Processos de Soldagem"}, {"c": "", "t": "24"}, {"c": "", "t": "II.3- Corrosão e Monitoração de Corrosão"}, {"c": "", "t": "28"}, {"c": "", "t": "II.4- Mecanismos de Deterioração de Equipamentos"}, {"c": "", "t": "32"}, {"c": "", "t": "II.5- Polímeros e materiais compósitos, refratários e Isolantes térmicos"}, {"c": "", "t": "24"}, {"c": "", "t": "Total do Módulo"}, {"c": "", "t": "136"}, {"c": "", "t": "MÓDULO III"}, {"c": "", "t": "DISCIPLINA"}, {"c": "", "t": "HORAS"}, {"c": "", "t": "ProteçãoContraDeterioração"}, {"c": "", "t": "III.1- Pintura e Revestimento Não Metálico"}, {"c": "", "t": "16"}, {"c": "", "t": "III.2- Revestimentos Metálicos"}, {"c": "", "t": "04"}, {"c": "", "t": "III.3- Proteção Catódica"}, {"c": "", "t": "12"}, {"c": "", "t": "III.4- Tratamento de Água e Inibidores de Corrosão"}, {"c": "", "t": "08"}, {"c": "", "t": "Total do Módulo"}, {"c": "", "t": "40"}, {"c": "", "t": "MÓDULO IV"}, {"c": "", "t": "DISCIPLINA"}, {"c": "", "t": "HORAS"}, {"c": "", "t": "Ensaios NãoDestrutivos"}, {"c": "", "t": "IV.1- Inspeção Visual"}, {"c": "", "t": "08"}, {"c": "", "t": "IV.2- Líquido Penetrante"}, {"c": "", "t": "08"}, {"c": "", "t": "IV.3- Partículas Magnéticas"}, {"c": "", "t": "08"}, {"c": "", "t": "IV.5- Medição de Espessuras"}, {"c": "", "t": "08"}, {"c": "", "t": "IV.6- Ultrassom"}, {"c": "", "t": "16"}, {"c": "", "t": "IV.7- END não convencional, radiografia, gamagrafia e novas técnicas"}, {"c": "", "t": "28"}, {"c": "", "t": "Total do Módulo"}, {"c": "", "t": "76"}, {"c": "", "t": "MÓDULO V"}, {"c": "", "t": "DISCIPLINA"}, {"c": "", "t": "HORAS"}, {"c": "", "t": "Técnicas deInspeção"}, {"c": "", "t": "V.1- Metalografia e Identificação de Materiais"}, {"c": "", "t": "12"}, {"c": "", "t": "V.2- Ensaios Mecânicos"}, {"c": "", "t": "08"}, {"c": "", "t": "V.3- Termografia"}, {"c": "", "t": "02"}, {"c": "", "t": "V.4 Cálculo de Taxas de Corrosão e Análise de Vida Remanescente"}, {"c": "", "t": "10"}, {"c": "", "t": "v.6 Raciocínio Lógico e Estatística Aplicada à Inspeção"}, {"c": "", "t": "04"}, {"c": "", "t": "Total do Módulo"}, {"c": "", "t": "36"}, {"c": "", "t": "MÓDULO VI"}, {"c": "", "t": "DISCIPLINA"}, {"c": "", "t": "HORAS"}, {"c": "", "t": "Inspeção deEquipamentos"}, {"c": "", "t": "VI.1- Vasos de Pressão e Torres de Fracionamento"}, {"c": "", "t": "24"}, {"c": "", "t": "VI.2- Permutadores de Calor"}, {"c": "", "t": "16"}, {"c": "", "t": "VI.3- Tanques de Armazenamento"}, {"c": "", "t": "16"}, {"c": "", "t": "VI.4- Tubulações e Dutos"}, {"c": "", "t": "32"}, {"c": "", "t": "VI.5- Caldeiras"}, {"c": "", "t": "24"}, {"c": "", "t": "VI.6- Fornos e Geradores de Vapor"}, {"c": "", "t": "20"}, {"c": "", "t": "VI.7- Dispositivos de Segurança"}, {"c": "", "t": "12"}, {"c": "", "t": "VI.8- Torres de Refrigeração"}, {"c": "", "t": "08"}, {"c": "", "t": "VI.9- Inspeção de Recebimento e Fabricação"}, {"c": "", "t": "12"}, {"c": "", "t": "VI.10 - Comunicação Técnica e Elaboração de Relatórios"}, {"c": "", "t": "04"}, {"c": "", "t": "VI.10- Aula Prática presencial ou visita técnica ou Estágio Supervisionado por PLH"}, {"c": "", "t": "40"}, {"c": "", "t": "Total do Módulo"}, {"c": "", "t": "208"}, {"c": "", "t": "Total do Treinamento"}, {"c": "", "t": "554"}, {"c": "dou-paragraph", "t": "ANEXO C - AMPLIAÇÃO DOS PRAZOS DE INSPEÇÃO DE CALDEIRAS CATEGORIA \"A\" COM BASE NA ADOÇÃO DE SISTEMAS DE SEGURANÇA (SIS/SGC)"}, {"c": "dou-paragraph", "t": "1. OBJETIVO"}, {"c": "dou-paragraph", "t": "1.1 Este Anexo estabelece os parâmetros técnicos e organizacionais que devem ser atendidos pelos estabelecimentos com SPIE que usufruem da ampliação dos prazos máximos de inspeção de caldeiras com base na adoção de Sistemas Instrumentados de Segurança (SIS) e/ou Sistemas de Gerenciamento de Combustão (SGC), conforme disposto na Norma Regulamentadora NR-13."}, {"c": "dou-paragraph", "t": "2. DISPOSIÇÕES GERAIS"}, {"c": "dou-paragraph", "t": "2.1 Os estabelecimentos que possuem SPIE e que almejem a ampliação do prazo de inspeção de segurança interna de caldeiras de Categoria A para até 48 (quarenta e oito) meses para o caso de SIS, ou de Caldeiras categoria B de operação contínua para 30 (trinta) meses, para o caso de SGC, devem atender o disposto na NR-13."}, {"c": "dou-paragraph", "t": "2.2 A ampliação de prazo é concedida individualmente por caldeira, condicionada à implantação e funcionamento adequado do SIS, para caldeiras categoria A, ou SGC, para caldeiras categoria B."}, {"c": "dou-paragraph", "t": "2.2.1 O Sindicato Predominante no Estabelecimento e a CIPA devem ser convidados, com antecedência mínima de 30 dias, para as referidas auditorias, bem como para as reuniões de abertura e encerramento, ficando a seu critério a participação."}, {"c": "dou-paragraph", "t": "2.3 O estabelecimento deve manter sistemática formal de testes para verificação da pressão de abertura das válvulas de segurança de cada caldeira com periodicidade máxima de 12 (doze) meses."}, {"c": "dou-paragraph", "t": "2.4 Para solicitar a ampliação do prazo de inspeção, o SPIE deve apresentar comprovação de que o SIS e/ou SGC estão implantados e funcionando adequadamente."}, {"c": "dou-paragraph", "t": "2.5 Quaisquer alterações nas funções instrumentadas de segurança do SIS ou SGC, sejam definitivas ou provisórias, devem ser registradas formalmente e justificadas por meio dos procedimentos internos de gerenciamento de mudanças."}, {"c": "dou-paragraph", "t": "2.6 A concessão da ampliação de prazo será suspensa nas seguintes situações:"}, {"c": "dou-paragraph", "t": "a) quando a caldeira deixar de atender aos requisitos estabelecidos pela NR-13;"}, {"c": "dou-paragraph", "t": "b) quando forem identificados desvios inaceitáveis nos parâmetros de funcionamento do SIS ou SGC; e"}, {"c": "dou-paragraph", "t": "c) quando forem identificadas não conformidades cuja tratativa não tenha ocorrido no prazo definido nos procedimentos internos."}, {"c": "dou-paragraph", "t": "Nota: A suspensão não implica na redução imediata dos prazos de inspeção ou qualquer alteração na aplicação dos itens constantes na NR-13 para estabelecimentos com SPIE o que deve ocorrer após o ciclo vigente do SIS."}, {"c": "anexo", "t": "ANEXO D - DETERMINAÇÃO DOS PRAZOS MÁXIMOS DE INSPEÇÃO COM BASE NA IMPLEMENTAÇÃO DE METODOLOGIA DE INSPEÇÃO BASEADA EM RISCO (IBR)"}, {"c": "dou-paragraph", "t": "1. OBJETIVO"}, {"c": "dou-paragraph", "t": "Este Anexo estabelece os parâmetros que devem ser atendidos pelos estabelecimentos com SPIE que optem por estabelecer os prazos máximos de inspeção dos equipamentos controlados pelo SPIE, com exceção de caldeiras e equipamentos sujeitos à chama, com base na implementação de metodologia documentada de Inspeção Baseada em Risco (IBR)."}, {"c": "dou-paragraph", "t": "2.DISPOSIÇÕES GERAIS"}, {"c": "dou-paragraph", "t": "2.1 A metodologia IBR deve estar integrada ao Programa de Gerenciamento de Riscos (PGR) do estabelecimento, nos termos da NR-01, com definição clara dos critérios de análise de risco, normas técnicas de referência adotadas e responsáveis por sua implementação e validação."}, {"c": "dou-paragraph", "t": "2.2 Quando forem realizados estudos de IBR em equipamentos específicos deve ser avaliado o impacto no PGR e alterado quando indicado pelo estudo."}, {"c": "dou-paragraph", "t": "2.3 Os equipamentos cujos prazos de inspeção sejam definidos por IBR devem ser referenciados no sistema de gestão dos equipamentos controlados pelo SPIE."}, {"c": "dou-paragraph", "t": "2.4 A implementação da metodologia deve seguir procedimentos escritos, baseados em normas técnicas nacionais ou internacionais reconhecidas, válidas no momento da criação do estudo de IBR."}, {"c": "dou-paragraph", "t": "2.5 A implementação da IBR deve ser conduzida por equipe multidisciplinar, composta por profissionais do próprio estabelecimento ou de empresas contratadas, com capacitação comprovada, sob responsabilidade técnica de um profissional do SPIE."}, {"c": "dou-paragraph", "t": "2.6 O responsável técnico pela equipe multidisciplinar deve ter autoridade e autonomia para a tomada de decisões."}, {"c": "dou-paragraph", "t": "2.7 Quando a IBR adotar abordagens qualitativas, semiquantitativas ou quantitativas a metologia utilizada deve estar de acordo com procedimentos escritos emitidos pelo estabelecimento."}, {"c": "dou-paragraph", "t": "2.8 Deve ser revisada, quando aplicável, a data e o escopo da próxima inspeção interna e / ou externa, com base na avaliação dos riscos (probabilidade x consequência), contendo os métodos de inspeção, suas localizações e abrangência, bem como suas respectivas efetividades."}, {"c": "dou-paragraph", "t": "Nota: Para equipamentos não NR-13, uma eventual alteração de prazos de inspeção pode ser assinada por responsável técnico."}, {"c": "dou-paragraph", "t": "2.9 Para que sejam mantidos os prazos definidos pela IBR, a metodologia definida para sua aplicação no estabelecimento deve prever as condições para atualização e reanálise dos relatórios da metodologia, com atualização da condição de risco, revisão do plano de inspeção e, quando aplicável, ajuste dos prazos definidos."}, {"c": "dou-paragraph", "t": "2.10 Quando um estudo de IBR indicar a necessidade de redução do prazo limite de inspeção, a empresa deve adotar as medidas mitigadoras correspondentes, formalizadas por justificativa técnica elaborada pela equipe multidisciplinar responsável."}, {"c": "dou-paragraph", "t": "Nota: Para equipamentos NR-13 a justificativa técnica deve estar respaldada pelo PLH do SPIE e arquivada no prontuário do equipamento."}, {"c": "dou-paragraph", "t": "2.11 Todas as decisões, premissas e revisões realizadas ao longo do ciclo de aplicação da IBR devem estar devidamente registradas e disponíveis para análise por auditorias internas, devendo ser objeto de amostragem nas auditorias externas."}, {"c": "dou-paragraph", "t": "ANEXO E - POSTERGAÇÃO DE PRAZOS MÁXIMOS DE INSPEÇÃO VISUAL INTERNA UTILIZANDO INSPEÇÃO NÃO INTRUSIVA (INI)"}, {"c": "dou-paragraph", "t": "1. OBJETIVO"}, {"c": "dou-paragraph", "t": "Este Anexo estabelece os requisitos e condições que devem ser observados pelos estabelecimentos com SPIE que desejam postergar os prazos da inspeção periódica visual interna intrusiva de vasos de pressão, mediante adoção da metodologia de Inspeção Não Intrusiva (INI), conforme previsto na Norma Regulamentadora NR-13."}, {"c": "dou-paragraph", "t": "2. DISPOSIÇÕES GERAIS"}, {"c": "dou-paragraph", "t": "2.1 Requisitos para adoção da metodologia"}, {"c": "dou-paragraph", "t": "2.1.1 Os estabelecimentos que possuem Serviço Próprio de Inspeção (SPIE) e que optarem por aplicar a metodologia de Inspeção Não Intrusiva (INI) devem atender ao disposto na NR-13."}, {"c": "dou-paragraph", "t": "2.1.2 A etapa de implementação inicial da metodologia INI deve ser acompanhada por um PLH do SPIE."}, {"c": "dou-paragraph", "t": "2.1.2.1 Um representante da entidade sindical predominante no estabelecimento deve ser convidado a participar."}, {"c": "dou-paragraph", "t": "2.2 Tolerância para atrasos"}, {"c": "dou-paragraph", "t": "As inspeções periódicas cujos prazos foram definidos com base na aplicação da metodologia de INI não possuem tolerância para eventuais atrasos, exceto nos casos em que seja aplicado o estudo da IBR e este estudo suporte a decisão da extensão do prazo para a inspeção interna prevista."}, {"c": "dou-paragraph", "t": "2.3 Documentação e rastreabilidade"}, {"c": "dou-paragraph", "t": "2.3.1 O SPIE deve garantir que todas as inspeções realizadas com base na metodologia INI sejam documentadas e rastreáveis, contendo:"}, {"c": "dou-paragraph", "t": "a) justificativa técnica da adoção da metodologia para cada equipamento;"}, {"c": "dou-paragraph", "t": "b) relatório técnico com a descrição dos ensaios utilizados e sua efetividade; e"}, {"c": "dou-paragraph", "t": "c) evidência de que os critérios técnicos e requisitos da NR-13 foram plenamente atendidos."}, {"c": "dou-paragraph", "t": "2.3.2 Esses registros devem estar integrados ao plano de inspeção do SPIE e permanecer disponíveis para auditorias e revisões técnicas."}, {"c": "dou-paragraph", "t": "ANEXO II - REQUISITOS DE AVALIAÇÃO DA CONFORMIDADE PARA SERVIÇOS PRÓPRIOS DE INSPEÇÃO DE EQUIPAMENTOS (SPIE)"}, {"c": "dou-paragraph", "t": "1. OBJETIVO"}, {"c": "dou-paragraph", "t": "Estabelecer os critérios e procedimentos para a avaliação da conformidade do SPIE, com foco na segurança, por meio do mecanismo de certificação, em atendimento aos requisitos estabelecidos na Instrução Normativa Inmetro para SPIE e na Norma Regulamentadora NR-13 do Mistério do Trabalho e Emprego."}, {"c": "dou-paragraph", "t": "1.1 Agrupamento para efeitos de certificação"}, {"c": "dou-paragraph", "t": "Para certificação do objeto destes Requisitos de Avaliação da Conformidade (RAC) aplica-se o conceito de escopo de serviço, definido como sendo o conjunto de instalações industriais submetidas a uma gestão comum (denominado neste documento como \"estabelecimento\")."}, {"c": "dou-paragraph", "t": "2. SIGLAS"}, {"c": "dou-paragraph", "t": "Para fins deste RAC são adotadas as siglas a seguir, além daquelas constantes nos documentos listados no item 3."}, {"c": "", "t": "CIPA"}, {"c": "", "t": "Comissão Interna de Prevenção de Acidentes e Assédio"}, {"c": "", "t": "CIPLAT"}, {"c": "", "t": "Comissão Interna de Prevenção de Acidentes em Plataformas"}, {"c": "", "t": "MTE"}, {"c": "", "t": "Ministério do Trabalho e Emprego"}, {"c": "", "t": "NQA"}, {"c": "", "t": "Nível de Qualidade Aceitável"}, {"c": "", "t": "PMTA"}, {"c": "", "t": "Pressão Máxima de Trabalho Admissível"}, {"c": "", "t": "RGI"}, {"c": "", "t": "Risco Grave e Iminente"}, {"c": "", "t": "RTDT"}, {"c": "", "t": "Regulamento Técnico de Dutos Terrestres para Movimentação dePetróleo, Derivados e Gás Natural"}, {"c": "dou-paragraph", "t": "3. DOCUMENTOS COMPLEMENTARES"}, {"c": "dou-paragraph", "t": "Para fins deste RAC, são adotados os documentos complementares a seguir, e aqueles estabelecidos no RGCP."}, {"c": "", "t": "Portaria Inmetro nº 200, de 2021, ou substitutiva."}, {"c": "", "t": "Requisitos Gerais de Certificação de Produtos - RGCP"}, {"c": "", "t": "ABNT NBR 5427"}, {"c": "", "t": "Guia para utilização da norma NBR 5426 - Planos de amostragem e procedimentos na inspeção por atributos."}, {"c": "", "t": "ABNT NBR 5426"}, {"c": "", "t": "Planos de amostragem e procedimentos na inspeção por atributos."}, {"c": "", "t": "ABNT NBR 17505"}, {"c": "", "t": "Armazenamento de Líquidos Inflamáveis e Combustíveis."}, {"c": "", "t": "ABNT NBR 16455"}, {"c": "", "t": "Vaso de pressão - Metodologia para Inspeção Não Intrusiva."}, {"c": "", "t": "NR-1"}, {"c": "", "t": "Norma Regulamentadora: Disposições Gerais e Gerenciamento de Riscos Ocupacionais."}, {"c": "", "t": "NR-13"}, {"c": "", "t": "Norma Regulamentadora de Caldeiras, Vasos de Pressão, Tubulações e Tanques Metálicos de Armazenamento."}, {"c": "", "t": "API RP 754"}, {"c": "", "t": "Process Safety Performance Indicators for the Refining and Petrochemical Industries"}, {"c": "dou-paragraph", "t": "3.1 Devem ser utilizadas as versões atualizadas dos documentos e das normas citadas, ou suas substitutivas (em caso de cancelamento) cabendo ao OCP, quando aplicável, promover as adequações necessárias nos procedimentos de avaliação da conformidade, a fim de possibilitar o uso da versão mais recente da norma/documento."}, {"c": "dou-paragraph", "t": "3.2 O prazo para a adoção da versão mais atualizada da norma ou sua substitutiva é de 12 (doze) meses ou o prazo de adequação da própria norma, devendo ser adotado o menor desses 2 (dois) prazos."}, {"c": "dou-paragraph", "t": "3.3 O prazo para a adoção da versão mais atualizada das NR é o estabelecido pelo MTE."}, {"c": "dou-paragraph", "t": "4. DEFINIÇÕES"}, {"c": "dou-paragraph", "t": "Para fins deste RAC, são adotadas as definições a seguir, complementadas pelas contidas na INI e nos documentos complementares citados no item 3."}, {"c": "dou-paragraph", "t": "4.1 Auditor de SPIE"}, {"c": "dou-paragraph", "t": "Profissional com competência e experiência para executar auditorias de SPIE pelo OCP, como membro de uma equipe auditora, e que atenda aos critérios estabelecidos pelo Anexo A deste RAC."}, {"c": "dou-paragraph", "t": "4.2 Auditoria de Acompanhamento"}, {"c": "dou-paragraph", "t": "Auditoria realizada com objetivo de verificar se ações corretivas foram ou estão sendo implementadas ou de verificar itens que não puderam ser plenamente avaliados nas demais auditorias, conforme estabelecido em auditoria anterior ou quando avaliada a necessidade pelo OCP."}, {"c": "dou-paragraph", "t": "4.3 Auditoria Extraordinária"}, {"c": "dou-paragraph", "t": "Auditoria realizada em um SPIE por decisão do OCP com objetivo de apurar denúncias, e/ou avaliar acidentes ou outras ocorrências excepcionais, ou mesmo para avaliar o impacto de alterações implementadas pelo SPIE que possam afetar a conformidade com os requisitos estabelecidos."}, {"c": "dou-paragraph", "t": "4.4 Observação"}, {"c": "dou-paragraph", "t": "Desvio que ocorre de forma pontual ou não abrangente ou comentário da equipe auditora para esclarecer pontos importantes de uma auditoria."}, {"c": "dou-paragraph", "t": "4.5 Preocupação"}, {"c": "dou-paragraph", "t": "Constatação, pelo OCP, de desvio não pontual ou abrangente que, se não tratado, deve evoluir para uma não conformidade."}, {"c": "dou-paragraph", "t": "5. MECANISMO DE AVALIAÇÃO DA CONFORMIDADE"}, {"c": "dou-paragraph", "t": "O mecanismo de avaliação da conformidade utilizado para o SPIE é a certificação."}, {"c": "dou-paragraph", "t": "6. ETAPAS DO PROCESSO DE CERTIFICAÇÃO"}, {"c": "dou-paragraph", "t": "6.1 Definição do Modelo de Certificação utilizado"}, {"c": "dou-paragraph", "t": "Este RAC estabelece o seguinte modelo de certificação:"}, {"c": "dou-paragraph", "t": "Modelo de Certificação 6 - Avaliação e aprovação do sistema de gestão do prestador de serviço."}, {"c": "dou-paragraph", "t": "6.2 Avaliação Inicial"}, {"c": "dou-paragraph", "t": "6.2.1 Solicitação de Certificação"}, {"c": "dou-paragraph", "t": "O estabelecimento deve encaminhar uma solicitação formal ao OCP, conforme definido no RGCP, acrescida dos documentos descritos a seguir:"}, {"c": "dou-paragraph", "t": "a) descrição detalhada das instalações do estabelecimento, incluindo; localização e layout geral; distribuição geográfica das unidades operacionais; identificação das instalações de processamento próprias e de terceiros;"}, {"c": "dou-paragraph", "t": "b) informações sobre atividades desenvolvidas por terceiros e instalações terceirizadas que podem afetar a certificação como equipamentos conectados a equipamentos do SPIE;"}, {"c": "dou-paragraph", "t": "c) informações gerais relevantes tais como: tipos e quantidade de equipamentos controlados pelo SPIE, enquadramento na NR-13, recursos humanos disponíveis e sua localização, funções e competências; e"}, {"c": "dou-paragraph", "t": "d) outras informações preliminares que vierem a ser solicitadas pelo OCP, necessárias ao planejamento das etapas de avaliação."}, {"c": "dou-paragraph", "t": "6.2.1.1 Situações especiais quanto à caracterização do estabelecimento devem ser objeto de decisão pelo OCP."}, {"c": "dou-paragraph", "t": "6.2.2 Análise da Solicitação e da Conformidade da Documentação"}, {"c": "dou-paragraph", "t": "Os critérios para solicitação, de análise da solicitação e da análise da conformidade da documentação devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "6.2.3 Auditoria Inicial"}, {"c": "dou-paragraph", "t": "6.2.3.1 Planejamento da Auditoria Inicial"}, {"c": "dou-paragraph", "t": "6.2.3.1.1 De posse das informações preliminares a equipe auditora deve fazer o planejamento da auditoria. O plano de auditoria deve ser elaborado, o programa de inspeção verificado, a amostragem definida, o efetivo conferido e a lista de verificação elaborada."}, {"c": "dou-paragraph", "t": "6.2.3.1.2 O planejamento deve ser elaborado considerando o porte, a complexidade, o risco e a localização das instalações industriais, sempre visando a verificação do atendimento aos requisitos da INI-SPIE e da NR-13."}, {"c": "dou-paragraph", "t": "6.2.3.2 Verificação do Programa de Inspeção"}, {"c": "dou-paragraph", "t": "6.2.3.2.1 O OCP deve conferir a programação enviada previamente para todos os equipamentos controlados pelo SPIE, devendo ser verificada a quantidade de equipamentos com inspeção interna ou externa vencida, para cada grupo de equipamentos conforme descrito no item 6.2.3.2.3. Como referência, deve ser utilizado o prazo estabelecido pelo PLH no relatório da última inspeção, não podendo ser superior aos valores estabelecidos pela NR-13 para estabelecimentos sem SPIE."}, {"c": "dou-paragraph", "t": "6.2.3.2.2 OCP deve verificar se os prazos aplicáveis a equipamentos não enquadrados na NR-13 estão definidos formalmente por PLH ou responsável técnico."}, {"c": "dou-paragraph", "t": "6.2.3.2.3 A porcentagem de inspeções internas ou externas vencidas, para cada grupo de equipamentos, deve ser verificada individualmente. Com base no valor apurado, devem ser observados os seguintes critérios:"}, {"c": "dou-paragraph", "t": "a) grupo A: não é tolerável desvio no programa de inspeção interna ou externa de caldeiras, seus dispositivos de segurança e de dutos terrestres que não sejam objeto de fiscalização específica pela Agência Nacional de Petróleo (ANP), nos termos do Regulamento Técnico de Dutos Terrestres (RTDT)."}, {"c": "dou-paragraph", "t": "Nota: Para dutos sujeitos à regulação própria da ANP, como os contemplados no RTDT, as regras de SPIE se aplicam de forma complementar, desde que não haja conflito com a legislação específica."}, {"c": "dou-paragraph", "t": "b) grupo B: para vasos de pressão categorizados na NR-13, dispositivos de segurança e alívio e tubulações externas, admite-se desvio de até 2% (dois por cento) no programa de inspeção interna ou externa, apurado separadamente."}, {"c": "dou-paragraph", "t": "c) grupo C: para tanques de armazenamento metálico enquadrados na NR-13 e demais equipamentos não categorizados pela norma, como vasos de pressão isentos, tanques atmosféricos, fornos e torres de resfriamento, admite-se desvio de até 5% (cinco por cento) no programa de inspeção interna ou externa, apurado separadamente."}, {"c": "dou-paragraph", "t": "d) grupo D: para tubulações internas, enquadradas ou não na NR-13, admite-se desvio de até 5% (cinco por cento) no programa de inspeção interna ou externa, apurado separadamente."}, {"c": "dou-paragraph", "t": "Nota 1: Para tubulações internas não enquadradas, o SPIE pode submeter ao OCP um plano técnico de adequação progressiva, que deve ser avaliado nas auditorias subsequentes."}, {"c": "dou-paragraph", "t": "Nota 2: A implementação de cada etapa do plano deve ser auditável e a tolerância máxima de 5% (cinco por cento) se aplica ao desvio em relação à programação acordada com o OCP."}, {"c": "dou-paragraph", "t": "6.2.3.2.4 O OCP deve verificar o atendimento aos prazos de inspeção definidos pela NR-13 e pelas especificações técnicas, inclusive para equipamentos em comodato."}, {"c": "dou-paragraph", "t": "6.2.3.2.5 Caso o OCP identifique, ainda que dentro das tolerâncias admitidas, equipamentos com inspeções atrasadas, deve ser verificado se foi emitida análise técnica assinada por PLH atestando sua integridade operacional."}, {"c": "dou-paragraph", "t": "6.2.3.2.5.1 Para dispositivos de segurança em atraso, o OCP deve verificar a avaliação de risco específica do equipamento protegido e as condições de operação segura até a regularização e estar nos registros do SPIE."}, {"c": "dou-paragraph", "t": "6.2.3.2.5.2 Constatados desvios acima dos critérios e não sanados nos prazos acordados, o OCP não deve realizar a auditoria, registrar impedimento/não conformidade conforme RGCP e aplicar as ações de acompanhamento previstas."}, {"c": "dou-paragraph", "t": "6.2.3.3 Definição da Amostragem"}, {"c": "dou-paragraph", "t": "O OCP deve estabelecer a amostra de acordo com a ABNT NBR 5426 e com a ABNT NBR 5427, utilizando Nível de Inspeção I e NQA 2,5. Para definição da amostra, devem ser observadas as seguintes regras:"}, {"c": "dou-paragraph", "t": "a) selecionar equipamentos e tubulações de diferentes instalações industriais, quando possível;"}, {"c": "dou-paragraph", "t": "b) selecionar vasos de pressão de diferentes tipos e de diferentes categorias, conforme definido na Norma Regulamentadora NR-13, incluindo também alguns não categorizados e em comodato;"}, {"c": "dou-paragraph", "t": "c) selecionar tubulações de diferentes sistemas, enquadradas e não enquadradas na Norma Regulamentadora NR-13;"}, {"c": "dou-paragraph", "t": "d) selecionar fornos e tanques de diferentes dimensões e características construtivas;"}, {"c": "dou-paragraph", "t": "e) Incluir na amostra todas as caldeiras, quando o número total de caldeiras instaladas for igual ou menor que 5 (cinco);"}, {"c": "dou-paragraph", "t": "Nota: Para estabelecimentos que possuam mais de cinco caldeiras, o tamanho da amostra deve ser estabelecido pela equipe auditora; e"}, {"c": "dou-paragraph", "t": "f) quando existente, a amostra deve incluir pelo menos uma esfera de armazenamento, dutos terrestres e tubulações externas ao estabelecimento."}, {"c": "dou-paragraph", "t": "6.2.3.4 Verificação do Efetivo"}, {"c": "dou-paragraph", "t": "6.2.3.4.1 O OCP deve verificar se o efetivo utilizado pelo SPIE atende aos critérios estabelecidos na INI-SPIE. Esta análise deve posteriormente ser complementada, durante a etapa de auditoria, por análise documental e entrevistas. O quantitativo de equipamentos por tipo e porte deve ser compatível com o programa de inspeção de equipamentos."}, {"c": "dou-paragraph", "t": "6.2.3.4.2 Tal verificação inclui a avaliação das situações em que foram adotados critérios diferenciados dos estabelecidos no Anexo A da INI-SPIE, tais como:"}, {"c": "dou-paragraph", "t": "a) subitem 2 - \"Fórmulas paramétricas\", valores distintos de \"T\";"}, {"c": "dou-paragraph", "t": "b) equipamentos distintos discriminados em linhas adicionais da Tabela 1; e"}, {"c": "dou-paragraph", "t": "c) redução de efetivo, conforme subitem 5.3."}, {"c": "dou-paragraph", "t": "6.2.3.5 Elaboração da Lista de Verificação"}, {"c": "dou-paragraph", "t": "Na fase de planejamento, o OCP deve elaborar uma Lista de Verificação, contendo todos os requisitos previstos no Anexo B deste RAC. Na etapa de avaliação inicial todos os itens da Lista devem ser verificados pelo OCP."}, {"c": "dou-paragraph", "t": "6.2.3.6 Realização da Auditoria"}, {"c": "dou-paragraph", "t": "6.2.3.6.1 O OCP deve designar pessoal competente e em número suficiente para executar as tarefas previstas no planejamento de auditoria."}, {"c": "dou-paragraph", "t": "6.2.3.6.2 Durante a auditoria, as informações pertinentes aos objetivos, escopo e critérios da auditoria, inclusive informações relativas às interfaces entre funções, atividades e processos devem ser analisados pelo OCP."}, {"c": "dou-paragraph", "t": "6.2.3.6.3 Se a documentação não puder ser fornecida, o OCP deve informar ao estabelecimento e decidir sobre a continuidade ou não da auditoria."}, {"c": "dou-paragraph", "t": "6.2.3.6.4 Durante a auditoria, o OCP deve verificar se as informações previamente enviadas, incluindo o programa da inspeção, atendem aos critérios estabelecidos."}, {"c": "dou-paragraph", "t": "6.2.3.6.5 Os requisitos que forem analisados por amostragem, como por exemplo, a programação, relatórios de inspeção de equipamentos e os requisitos de campo, devem ser verificados conforme item 6.2.3.2, sendo a programação analisada de forma integral, e os demais requisitos avaliados por amostragem, conforme item 6.2.3.3."}, {"c": "dou-paragraph", "t": "6.2.3.6.6 O OCP deve realizar entrevistas durante o processo de auditoria de SPIE. Estas entrevistas devem incluir necessariamente representantes da CIPA ou CIPLAT e a representação sindical da categoria profissional predominante no estabelecimento. É importante que o entrevistado esteja isento de conflito de interesses, com sua identificação preservada. Outras entrevistas, a critério do OCP, também podem ser realizadas."}, {"c": "dou-paragraph", "t": "6.2.3.6.7 No caso de SPIE com bases de operação em mais de um estado ou município, devem ser entrevistados representantes sindicais de cada base. Para o caso de SPIE com base de operação que possua mais de uma representação sindical, deve ser entrevistada a representação sindical predominante no estabelecimento."}, {"c": "dou-paragraph", "t": "6.2.3.6.8 A designação do Representante da CIPA ou da CIPLAT deve respeitar os seguintes critérios:"}, {"c": "dou-paragraph", "t": "a) o entrevistado deve ser escolhido entre os representantes eleitos da CIPA ou da CIPLAT; e"}, {"c": "dou-paragraph", "t": "b) o entrevistado deve ser indicado em reunião da CIPA ou da CIPLAT precedente à auditoria."}, {"c": "dou-paragraph", "t": "6.2.3.6.9 Para estabelecimento com instalações dispersas, os representantes da CIPA devem ser indicados de diferentes instalações, de forma que, concluído um ciclo de certificação, sejam entrevistados representantes da maior parte das instalações."}, {"c": "dou-paragraph", "t": "6.2.3.6.10 As entrevistas devem ser programadas durante a fase de planejamento da auditoria, devendo ser programadas de forma que que o OCP disponha de tempo hábil para promover a análise e investigação de demandas trazidas pelos entrevistados."}, {"c": "dou-paragraph", "t": "Nota: Caso a entrevista não venha a ser realizada no momento programado, cabe ao OCP analisar a viabilidade de promover mudanças no plano de auditoria."}, {"c": "dou-paragraph", "t": "6.2.3.6.11 Caso a(s) representação(ões) sindical(is) convidadas não compareçam às entrevistas, o auditor líder deverá registrar formalmente o fato e dar continuidade à auditoria conforme o planejamento aprovado."}, {"c": "dou-paragraph", "t": "6.2.3.7 Verificação de Conformidade"}, {"c": "dou-paragraph", "t": "A coleta de informações para verificação inclui um ou mais dos seguintes métodos, definidos pelo OCP:"}, {"c": "dou-paragraph", "t": "a) verificação da documentação enviada com as informações preliminares;"}, {"c": "dou-paragraph", "t": "b) verificação da documentação pertinente, disponível no estabelecimento;"}, {"c": "dou-paragraph", "t": "c) realização das entrevistas;"}, {"c": "dou-paragraph", "t": "d) verificação das instalações do SPIE;"}, {"c": "dou-paragraph", "t": "e) verificação das instalações industriais, oficinas e laboratórios;"}, {"c": "dou-paragraph", "t": "f) verificação de equipamentos de terceiros em comodato; e"}, {"c": "dou-paragraph", "t": "g) verificação da aparelhagem do SPIE."}, {"c": "dou-paragraph", "t": "6.2.4 Tratamento de Não Conformidades e Preocupações na Etapa de Avaliação Inicial"}, {"c": "dou-paragraph", "t": "Os critérios para tratamento de não conformidades na etapa de avaliação inicial devem seguir os requisitos estabelecidos no RGCP, observado o disposto no subitem 6.5 deste RAC."}, {"c": "dou-paragraph", "t": "6.2.5 Emissão do Certificado de Conformidade"}, {"c": "dou-paragraph", "t": "6.2.5.1 A Análise crítica deve seguir o disposto no RGCP, observado o que segue."}, {"c": "dou-paragraph", "t": "6.2.5.2 A Comissão de Certificação deve ser constituída pelo OCP, com composição tripartite e paritária, composta por membros indicados por suas representações e que representem o Ministério do Trabalho e Emprego, membros que representem os trabalhadores dos estabelecimentos e membros que representem os estabelecimentos."}, {"c": "dou-paragraph", "t": "6.2.5.3 Os critérios para emissão do Certificado de Conformidade na etapa de avaliação inicial devem seguir os requisitos estabelecidos no RGCP. A validade do certificado é de 48 (quarenta e oito) meses, contados a partir da data de sua emissão."}, {"c": "dou-paragraph", "t": "6.3 Avaliação de Manutenção"}, {"c": "dou-paragraph", "t": "Os critérios para a avaliação da manutenção devem seguir os requisitos estabelecidos no RGCP sendo que quaisquer alterações nas condições técnico-organizacionais que deram origem à concessão inicial da certificação devem ser imediatamente informadas ao OCP, que, a qualquer tempo (independentemente da etapa de manutenção) pode determinar a necessidade de nova avaliação."}, {"c": "dou-paragraph", "t": "6.3.1 Auditoria de Manutenção"}, {"c": "dou-paragraph", "t": "6.3.1.1 Planejamento da Auditoria de Manutenção"}, {"c": "dou-paragraph", "t": "6.3.1.1.1 O OCP deve realizar auditorias de manutenção a cada 12 (doze) meses, contados a partir da data de emissão do certificado. A periodicidade entre auditorias de manutenção pode ser ampliada para 18 (dezoito) meses quando estiverem presentes todas as seguintes condições:"}, {"c": "dou-paragraph", "t": "a) ter sido certificado há pelo menos 2 (dois) ciclos de certificação;"}, {"c": "dou-paragraph", "t": "b) não ter tido a certificação suspensa nos últimos 2 (dois) ciclos de certificação;"}, {"c": "dou-paragraph", "t": "c) não ter sido advertido no último ciclo; e"}, {"c": "dou-paragraph", "t": "d) não ter recebido não conformidades categorizadas como \"A\" no último ciclo."}, {"c": "dou-paragraph", "t": "Nota 1: A ampliação de periodicidade entre auditorias de manutenção pode ser revogada a qualquer tempo em caso de ocorrência de acidente maior, conforme decisão do OCP, ou caso o SPIE seja objeto de advertência ou suspensão."}, {"c": "dou-paragraph", "t": "Nota 2: O aumento de periodicidade entre auditorias de manutenção deve ser implementado a partir do início do ciclo subsequente a sua solicitação."}, {"c": "dou-paragraph", "t": "6.3.1.1.2 Quando o SPIE tiver aplicado metodologias alternativas reconhecidas pela NR-13, tais como Inspeção Não Intrusiva (INI) ou Inspeção Baseada em Risco (IBR), para definição ou postergação de prazos de inspeção, o OCP deve:"}, {"c": "dou-paragraph", "t": "a) incluir na amostragem pelo menos um equipamento avaliado por cada metodologia aplicada (INI e/ou IBR), com verificação documental e, quando aplicável, testemunho de campo;"}, {"c": "dou-paragraph", "t": "b) avaliar a conformidade técnica das metodologias empregadas, considerando a justificativa, critérios de aceitação, análise de risco, qualificação da equipe e rastreabilidade das decisões;"}, {"c": "dou-paragraph", "t": "6.3.1.1.3 As informações preliminares para a auditoria devem ser encaminhadas em até 30 (trinta) dias antes de seu início e devem conter:"}, {"c": "dou-paragraph", "t": "a) alterações no quadro de pessoal próprio;"}, {"c": "dou-paragraph", "t": "b) alterações nos itens controlados;"}, {"c": "dou-paragraph", "t": "c) alterações nas atribuições de cada função;"}, {"c": "dou-paragraph", "t": "d) alterações na infraestrutura, ambiente de trabalho;"}, {"c": "dou-paragraph", "t": "e) relação de procedimentos, manuais ou instruções ligadas às atividades do SPIE;"}, {"c": "dou-paragraph", "t": "f) ocorrência envolvendo itens controlados pelo SPIE classificada como acidente maior ou evento de segurança de processo que possa ser classificado como Tier 2 conforme API RP 754 ou metodologia similar aprovada pelo OCP;"}, {"c": "dou-paragraph", "t": "g) equipamentos controlados onde estão sendo aplicadas as metodologias de INI, SIS ou IBR;"}, {"c": "dou-paragraph", "t": "h) registro de eventuais fiscalizações correlatas à NR-13 ou SPIE efetuadas pelo MTE, ANP ou outro órgão fiscalizador;"}, {"c": "dou-paragraph", "t": "i) evolução de eventuais planos de ajustamento que tenham sido aprovados;"}, {"c": "dou-paragraph", "t": "j) indicadores de Recomendações de Inspeção e atendimento ao programa de inspeção;"}, {"c": "dou-paragraph", "t": "k) equipamentos de terceiros em comodato; e"}, {"c": "dou-paragraph", "t": "l) status operacional dos equipamentos controlados pelo SPIE que estejam em manutenção, fora de operação ou desativados."}, {"c": "dou-paragraph", "t": "6.3.1.2 Verificação do Programa de Inspeção"}, {"c": "dou-paragraph", "t": "6.3.1.2.1 A verificação do programa deve ser realizada segundo o subitem 6.2.3.2, exceto no que se refere à determinação da porcentagem de inspeções internas e de inspeções externas vencidas para cada grupo de itens controlados, que deve seguir os seguintes critérios:"}, {"c": "dou-paragraph", "t": "a) grupo A: não é tolerável desvio na programação de inspeção externa ou interna para caldeiras e seus dispositivos de segurança e dutos terrestres que não sejam objeto de fiscalização específica por parte da ANP."}, {"c": "dou-paragraph", "t": "b) grupo B: para vasos de pressão categorizados na NR-13 e demais dispositivos de segurança e alívio, é tolerável um desvio de até 0,5% (meio por cento) na programação de inspeção interna ou externa."}, {"c": "dou-paragraph", "t": "c) grupo C: para tanques de armazenamento metálico NR-13 e outros equipamentos não categorizados pela NR-13, tais como vasos, demais tanques de armazenamento, fornos, torres de resfriamento etc., é tolerável um desvio de até 5% (cinco por cento) na programação de inspeção interna ou externa."}, {"c": "dou-paragraph", "t": "d) grupo D: para o caso de tubulações internas, enquadradas ou não na NR-13, pode ser tolerado um desvio de até 5% (cinco por cento)."}, {"c": "dou-paragraph", "t": "Nota 1: Caso sejam identificados, ainda que dentro das tolerâncias admitidas, equipamentos ou tubulações com inspeções atrasadas, deve ser emitida análise técnica assinada por PLH atestando sua integridade operacional. Para dispositivos de segurança em atraso, a justificativa técnica deve incluir avaliação de risco para o equipamento por eles protegido. Tais análises devem ser incluídas nos registros do SPIE e submetidas à análise do OCP durante a auditoria."}, {"c": "dou-paragraph", "t": "6.3.1.2.2 Caso seja constatada a repetição de atraso na inspeção de um mesmo equipamento ou item controlado em duas auditorias consecutivas, ainda que dentro da tolerância admitida neste RAC, configura-se o não tratamento de desvio, e o requisito será considerado não conforme. Durante a auditoria em que a não conformidade for constatada, o estabelecimento deve apresentar justificativa técnica assinada por PLH, atestando a condição de integridade para operação segura do equipamento ou item em atraso, com a data prevista para execução da inspeção e os cuidados adotados para garantir que a postergação não implique riscos à segurança ou à integridade do equipamento."}, {"c": "dou-paragraph", "t": "6.3.1.3 Definição da Amostragem"}, {"c": "dou-paragraph", "t": "6.3.1.3.1 O OCP deve estabelecer a amostra de acordo com a Norma ABNT NBR 5426 e ABNT NBR 5427, utilizando Nível de Inspeção I e NQA 2,5."}, {"c": "dou-paragraph", "t": "6.3.1.3.2 Para definição da amostra, devem ser observadas as regras estabelecidas no subitem 6.2.3.3."}, {"c": "dou-paragraph", "t": "6.3.1.3.3 O OCP deve assegurar que, ao término de um ciclo de certificação, todos os requisitos da LV e pelo menos um equipamento ou tubulações de cada unidade do estabelecimento tenha sido verificado."}, {"c": "dou-paragraph", "t": "6.3.1.4 Verificação do Efetivo"}, {"c": "dou-paragraph", "t": "6.3.1.4.1 A verificação do efetivo deve ser realizada de acordo com o subitem 6.2.3.4 deste RAC."}, {"c": "dou-paragraph", "t": "6.3.1.5 Elaboração da Lista de Verificação"}, {"c": "dou-paragraph", "t": "6.3.1.5.1 Na fase de planejamento, o OCP deve elaborar uma Lista de Verificação, contendo todos os requisitos previstos no Anexo B deste RAC."}, {"c": "dou-paragraph", "t": "6.3.1.5.2 O OCP deve considerar, em cada auditoria de manutenção, uma porcentagem dos requisitos não classificados como essenciais ou modificados em relação à auditoria anterior, de forma que, ao término do ciclo, todos os requisitos da Lista de Verificação tenham sido verificados."}, {"c": "dou-paragraph", "t": "Para fins deste item, consideram-se:"}, {"c": "dou-paragraph", "t": "a) requisitos essenciais: efetivo de pessoal, programa de inspeção, rastreabilidade de arquivos, relatórios de inspeção, recomendações de inspeção, reclamações e requisitos de campo;"}, {"c": "dou-paragraph", "t": "b) requisitos modificados: aqueles com alterações significativas desde a última auditoria, como em capacitação do pessoal e indicadores de desempenho; e"}, {"c": "dou-paragraph", "t": "c) requisitos objeto de não conformidades ou preocupações na auditoria anterior."}, {"c": "dou-paragraph", "t": "6.3.1.6 Realização da Auditoria"}, {"c": "dou-paragraph", "t": "6.3.1.6.1 O OCP deve verificar, para a amostra definida em 6.3.1.3, se os dados coletados nas unidades estão de acordo com os dados registrados nos arquivos do SPIE ou descritos nas informações preliminares."}, {"c": "dou-paragraph", "t": "6.3.1.6.2 Não podem compor a verificação de campo equipamentos, sistemas ou unidades declarados como \"fora de operação\", em \"stand-by\" ou \"em manutenção\" pelo estabelecimento."}, {"c": "dou-paragraph", "t": "6.3.1.6.3 O OCP deve verificar se os itens controlados considerados como fora de operação estão conforme procedimento técnico do estabelecimento que contemple a metodologia de isolamento do sistema, tal como: bloqueio e raqueteamento, duplo bloqueio com alívio entre as válvulas e abertura para atmosfera e preveja as situações que demandem a conservação dos equipamentos que fiquem nesta condição de inatividade para garantir sua integridade, incluindo inertização, bloqueio e/ou isolamento."}, {"c": "dou-paragraph", "t": "6.3.1.6.4 Durante a verificação, o OCP deve confirmar que a documentação exigida pela NR-13 (relatórios, registros de condição operacional e recomendações) está disponível, íntegra e atualizada, avaliando prazos, responsáveis e implementação."}, {"c": "dou-paragraph", "t": "6.3.1.6.5 Na amostra selecionada previamente, deve ser verificado se:"}, {"c": "dou-paragraph", "t": "a) a localização e as características dos equipamentos e tubulações controlados conferem com o prescrito nos arquivos;"}, {"c": "dou-paragraph", "t": "b) a identificação do equipamento é correta, clara e facilmente visível. As tubulações devem estar identificadas conforme procedimento elaborado pelo estabelecimento, nos termos da NR-13;"}, {"c": "dou-paragraph", "t": "c) a categoria do equipamento, quando aplicável, está correta e atende as exigências da NR-13;"}, {"c": "dou-paragraph", "t": "d) as placas de identificação estão devidamente afixadas, são acessíveis e visíveis, e atendem aos requisitos legais e normativos;"}, {"c": "dou-paragraph", "t": "e) existem os dispositivos de segurança obrigatórios, lacrados, se estão claramente identificados, se suas características conferem com as informações de arquivo, e se possuem proteção contra bloqueios inadvertidos, seja por meio de controle administrativo ou dispositivo físico, conforme disposições da NR-13;"}, {"c": "dou-paragraph", "t": "f) os manômetros, indicadores de pressão e/ou transmissores de pressão dos itens enquadrados na NR-13 e indicadores de nível de caldeiras reúnem condições operacionais aceitáveis, e se estão identificados."}, {"c": "dou-paragraph", "t": "Nota: Em sistemas de geração de vapor (como em caldeiras) caso os instrumentos de indicação de nível estejam fora de operação, o OCP deve verificar se os instrumentos alternativos estão operacionais e possuem planos de calibração vigentes;"}, {"c": "dou-paragraph", "t": "g) a calibração dos instrumentos segue plano de manutenção preventiva e os procedimentos os aplicáveis, se é realizada com a frequência estabelecida e se a oficina para calibração atende as necessidades dos serviços;"}, {"c": "dou-paragraph", "t": "h) o equipamento amostrado apresenta vazamentos ou deteriorações severas que possam interferir com a segurança das pessoas e a preservação do meio ambiente, ou se não possui recomendação de inspeção vigente, modificada ou cancelada sem a devida análise e justificativa técnica emitida pelo PLH;"}, {"c": "dou-paragraph", "t": "i) o acesso ao equipamento é seguro e apresenta bom estado de conservação;"}, {"c": "dou-paragraph", "t": "j) o valor de PMTA do equipamento é compatível com a pressão de abertura do dispositivo de segurança, considerando as prescrições da NR-13;"}, {"c": "dou-paragraph", "t": "k) as inspeções e intervenções estão sendo adequadamente anotadas no registro de segurança e se conferem com as existentes nos arquivos do SPIE; e"}, {"c": "dou-paragraph", "t": "l) os equipamentos estáticos que devem ser controlados pelo SPIE estão incluídos no programa de inspeção e são rastreáveis com as instalações físicas, conforme definido no escopo técnico do SPIE."}, {"c": "dou-paragraph", "t": "6.3.1.6.6 As demais etapas da auditoria de manutenção seguem o estabelecido na auditoria inicial:"}, {"c": "dou-paragraph", "t": "a) para apurar denúncias referentes a um SPIE certificado, nos casos que este não apresente evidências suficientes para apuração do ocorrido pelo OCP;"}, {"c": "dou-paragraph", "t": "b) para avaliar acidentes ocorridos em equipamentos sob controle do SPIE, que tenham resultado em morte de trabalhador(es), internação hospitalar de trabalhador(es), ou acidente de segurança de processo enquadrado como Tier 1, conforme API RP 754 ou metodologia similar aprovada pelo OCP; e"}, {"c": "dou-paragraph", "t": "c) para avaliar alterações significativas no perfil avaliado, conforme definido neste RAC."}, {"c": "dou-paragraph", "t": "6.3.2 Tratamento de Não Conformidades na Avaliação de Manutenção"}, {"c": "dou-paragraph", "t": "Os requisitos para o tratamento de não conformidades na etapa de manutenção devem seguir o disposto no RGCP, observado o disposto no subitem 6.5 deste RAC."}, {"c": "dou-paragraph", "t": "6.3.3 Confirmação da Manutenção"}, {"c": "dou-paragraph", "t": "A confirmação da manutenção deve seguir os requisitos estabelecidos pelo RGC"}, {"c": "dou-paragraph", "t": "6.4 Avaliação de Recertificação"}, {"c": "dou-paragraph", "t": "6.4.1 Os critérios para a avaliação de recertificação devem seguir o RGCP, devendo ser concluída antes do término da validade do certificado anteriormente emitido."}, {"c": "dou-paragraph", "t": "6.4.2 O planejamento da auditoria de recertificação deve seguir os critérios estabelecidos para a etapa de auditoria de manutenção deste RAC. As demais etapas, elaboração da LV, auditoria, tratamento de não conformidades e emissão do certificado devem seguir os critérios estabelecidos para a avaliação inicial."}, {"c": "dou-paragraph", "t": "6.5 Tratamento de Desvios no Processo de Certificação de SPIE"}, {"c": "dou-paragraph", "t": "6.5.1 As não conformidades devem ser classificadas em categorias conforme critérios definidos a seguir:"}, {"c": "dou-paragraph", "t": "a) Categoria A RGI: Desvios constatados em requisitos desta categoria, independentemente da quantidade amostral definida, caracterizam o não atendimento do requisito e devem ser corrigidos durante o período da auditoria. Apesar da correção do desvio, a não conformidade é mantida, sendo então contabilizada junto com as de categoria \"A\" comum, para fins de aplicação da quantidade permitida de não conformidades desse tipo."}, {"c": "dou-paragraph", "t": "Caso a ação imediata não possa ser implementada, a auditoria deve ser interrompida, e o OCP deve decidir sobre as ações aplicáveis, estando o SPIE sujeito às penalidades estabelecidas neste RAC."}, {"c": "dou-paragraph", "t": "A implementação de ações corretivas e preventivas, para evitar a repetição dos desvios, deve ser realizada em até 90 (noventa) dias."}, {"c": "dou-paragraph", "t": "O OCP deve decidir se é aplicável a realização de auditoria de acompanhamento, conforme previsto neste RAC."}, {"c": "dou-paragraph", "t": "Os requisitos que devem estar nesta categoria são aqueles cujo não cumprimento:"}, {"c": "dou-paragraph", "t": "a1) pode comprometer seriamente a segurança de pessoas, instalações ou meio ambiente;"}, {"c": "dou-paragraph", "t": "a2) pode resultar em danos significativos à integridade física dos trabalhadores; e"}, {"c": "dou-paragraph", "t": "a3) pode causar falhas críticas nos sistemas de gestão."}, {"c": "dou-paragraph", "t": "b) Categoria A Comum: São permitidas até 3 (três) não conformidades nesta categoria, que devem ser objeto de plano de ação aprovado pelo OCP."}, {"c": "dou-paragraph", "t": "As não conformidades devem ser tratadas pelo SPIE até a próxima auditoria, com evidência de execução das ações corretivas e preventivas."}, {"c": "dou-paragraph", "t": "O OCP deve avaliar a eficácia do tratamento durante a auditoria subsequente."}, {"c": "dou-paragraph", "t": "Os requisitos nesta categoria são aqueles que:"}, {"c": "dou-paragraph", "t": "b.1) são importantes para a conformidade geral do sistema de gestão, mas cujo não cumprimento não representa um risco imediato grave;"}, {"c": "dou-paragraph", "t": "b.2) podem afetar a eficiência operacional, a qualidade do produto ou a satisfação do cliente; e"}, {"c": "dou-paragraph", "t": "b.3) podem não estar totalmente em conformidade com requisitos documentais ou procedimentais, mas não comprometem a segurança crítica."}, {"c": "dou-paragraph", "t": "c) Categoria B: são permitidas até 5 (cinco) não conformidades, que devem ser tratadas pelo SPIE até a próxima auditoria. Requisitos nesta categoria são aqueles que:"}, {"c": "dou-paragraph", "t": "c.1) são menos críticos para a conformidade geral do sistema de gestão;"}, {"c": "dou-paragraph", "t": "c.2) podem estar relacionados a práticas recomendadas, boas práticas de fabricação ou detalhes específicos que não afetam diretamente a segurança ou a conformidade legal essencial; e"}, {"c": "dou-paragraph", "t": "c.3) são passíveis de não conformidades que podem ser resolvidas dentro do ciclo regular de auditorias."}, {"c": "dou-paragraph", "t": "6.5.2 Caso seja constatada pelo OCP alguma não conformidade já identificada anteriormente pelo SPIE, que seja decorrente da mesma causa e esteja em tratamento adequado, o OCP pode a seu critério, aplicar apenas uma preocupação no requisito."}, {"c": "dou-paragraph", "t": "6.5.3 Caso seja observada mais de uma não conformidade ou preocupação que tenham a mesma causa básica, o OCP pode, a seu critério, aplicar apenas uma única não conformidade, deixando explícito no relatório de auditoria as razões para a tomada de decisão."}, {"c": "dou-paragraph", "t": "6.5.4 Deve ser considerada como repetição de não conformidades a ocorrência de desvios acima dos critérios de aceitação, em auditorias consecutivas dentro de um mesmo ciclo e que tenham a mesma causa básica."}, {"c": "dou-paragraph", "t": "6.5.5 Para desvios caracterizados como preocupação não existe limite de aceitação, porém a preocupação deve ser tratada pelo SPIE até a próxima auditoria. Preocupações não tratadas neste período devem ser consideradas como não conformidades na auditoria subsequente."}, {"c": "dou-paragraph", "t": "6.5.6 Para as não conformidades categoria A RGI ou Categoria A Comum, o OCP pode requerer auditorias de acompanhamento, com início em prazo não inferior a 60 (sessenta) dias e não superior a 180 (cento e oitenta) dias."}, {"c": "dou-paragraph", "t": "6.5.7 As não conformidades devem ser informadas ao SPIE preferencialmente até o término da auditoria. Em casos particulares, após análise pelo OCP, e discussão com o estabelecimento, podem ocorrer alterações das constatações informadas na auditoria. As razões para cada alteração devem ser formalmente transmitidas ao SPIE."}, {"c": "dou-paragraph", "t": "6.5.8 O representante do SPIE deve preencher um formulário com as respectivas ações corretivas e de abrangência, devendo remetê-lo ao OCP em até 15 (quinze) dias, contados a partir da data de recebimento da não conformidade."}, {"c": "dou-paragraph", "t": "6.5.9 No caso de não cumprimento dos prazos estabelecidos para as respectivas ações corretivas, o SPIE fica sujeito às penalidades estabelecidas neste RAC."}, {"c": "dou-paragraph", "t": "6.5.10 As não conformidades devem ser tratadas conforme estabelecido no RGCP."}, {"c": "dou-paragraph", "t": "6.6 Tratamento de Alterações que afetam a Certificação"}, {"c": "dou-paragraph", "t": "6.6.1 Consideram-se como circunstâncias que afetam a certificação de SPIE e que devem ser comunicadas formalmente ao OCP no prazo máximo de 03 (três) dias úteis:"}, {"c": "dou-paragraph", "t": "a) Ocorrências em equipamentos controlados pelo SPIE que tenham como consequência uma das seguintes situações:"}, {"c": "dou-paragraph", "t": "a1) morte de trabalhador(es);"}, {"c": "dou-paragraph", "t": "a2) internação hospitalar de trabalhador(es); e"}, {"c": "dou-paragraph", "t": "a3) acidente de segurança de processo enquadrado como Tier 1, conforme API RP 754, ou metodologia similar aprovada pelo OCP."}, {"c": "dou-paragraph", "t": "6.6.2 Para o tratamento das circunstâncias que afetam a certificação de SPIE, o OCP deve executar uma auditoria extraordinária, no prazo máximo de 180 (cento e oitenta) dias, contados a partir do recebimento da informação, nas seguintes situações:"}, {"c": "dou-paragraph", "t": "a) acréscimo ou redução de itens controlados superior a 10% (dez por cento) do total ou superior a 1.000 itens controlados, o que for menor;"}, {"c": "dou-paragraph", "t": "b) acréscimo de novas unidades operacionais, independentemente do número de equipamentos instalados; e"}, {"c": "dou-paragraph", "t": "c) ocorrência de acidente maior em equipamentos controlados pelo SPIE devendo o estabelecimento comunicar o OCP em até 3 (três) dias úteis."}, {"c": "dou-paragraph", "t": "6.6.3 Consideram-se como circunstâncias que afetam a certificação de SPIE e que devem ser comunicadas formalmente ao OCP no prazo máximo de 30 (trinta) dias, contados a partir da data de ocorrência:"}, {"c": "dou-paragraph", "t": "a) ocorrências de acidentes não enquadrados como \"acidente maior\" em equipamentos controlados pelo SPÌE que acarretem diretamente redução de carga ou parada não programada da unidade;"}, {"c": "dou-paragraph", "t": "b) alterações maiores do que 10% (dez por cento), por função, no quadro de pessoal do SPIE;"}, {"c": "dou-paragraph", "t": "c) alterações nas instalações, quando houver acréscimo ou redução de itens controlados superior a 10% (dez por cento) do total ou superior a 1.000 itens controlados, o que for menor;"}, {"c": "dou-paragraph", "t": "d) alterações nas instalações, quando forem acrescidas ou removidas unidades, independentemente do número de equipamentos instalados;"}, {"c": "dou-paragraph", "t": "e) alterações na constituição legal, comercial ou organizacional do estabelecimento; e"}, {"c": "dou-paragraph", "t": "f) alterações na responsabilidade pela gestão do SPIE."}, {"c": "dou-paragraph", "t": "6.7 Solicitação de uso da metodologia de Inspeção Não Intrusiva (INI) ou de adoção de Sistemas Instrumentados de Segurança (SIS)"}, {"c": "dou-paragraph", "t": "6.7.1 A solicitação de uso da metodologia de Inspeção Não Intrusiva (INI) ou de adoção de Sistemas Instrumentados de Segurança (SIS), somente pode ocorrer após a concessão da certificação, como parte da avaliação de manutenção ou recertificação."}, {"c": "dou-paragraph", "t": "6.7.2 O OCP deve incluir na amostragem pelo menos um equipamento inspecionado pela metodologia, para verificação da correta aplicação do previsto nos Anexos E e F da INI-SPIE."}, {"c": "dou-paragraph", "t": "7. TRATAMENTO DE RECLAMAÇÕES"}, {"c": "dou-paragraph", "t": "Os critérios de tratamento de reclamações seguem os critérios estabelecidos no RGCP e na INI-SPIE."}, {"c": "dou-paragraph", "t": "8. TRANSFERÊNCIA DA CERTIFICAÇÃO"}, {"c": "dou-paragraph", "t": "Os critérios de transferência da certificação seguem os critérios estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "9. ENCERRAMENTO DA CERTIFICAÇÃO"}, {"c": "dou-paragraph", "t": "Os critérios para Encerramento da Certificação devem seguir os requisitos do RGCP."}, {"c": "dou-paragraph", "t": "10. RESPONSABILIDADES E OBRIGAÇÕES"}, {"c": "dou-paragraph", "t": "Os critérios para responsabilidades e obrigações devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "Nota: Para efeitos deste RAC, aplicam-se ao \"Estabelecimento\" as disposições do RGCP previstas para o \"Fornecedor\"."}, {"c": "dou-paragraph", "t": "11. PENALIDADES"}, {"c": "dou-paragraph", "t": "11.1 Os critérios para aplicação de penalidades devem seguir o RGCP, observado o disposto a seguir."}, {"c": "dou-paragraph", "t": "11.2 A advertência deve ser emitida nas seguintes circunstâncias:"}, {"c": "dou-paragraph", "t": "a) quando o SPIE reincidir consecutivamente em não conformidades de mesma causa específica;"}, {"c": "dou-paragraph", "t": "b) quando o SPIE não informar ou informar de modo incorreto circunstâncias que tenham ocorrido no estabelecimento ou no SPIE e que podem afetar a certificação;"}, {"c": "dou-paragraph", "t": "c) quando o SPIE utilizar indevidamente o certificado de SPIE;"}, {"c": "dou-paragraph", "t": "d) quando o SPIE ultrapassar os limites estabelecidos para o número de não conformidades estabelecidos neste RAC;"}, {"c": "dou-paragraph", "t": "e) quando o SPIE omitir ou dificultar o acesso às informações relevantes para o processo;"}, {"c": "dou-paragraph", "t": "f) quando o deixar de tratar, dentro do prazo estabelecido, não Conformidades ou planos de ação acordados com o OCP; e"}, {"c": "dou-paragraph", "t": "g) quando ocorrerem incidentes ou acidentes em itens controlados pelo SPIE e ficar efetivamente comprovado, por meio de auditoria ou evidências documentais, que houve negligência, imperícia ou imprudência por parte do SPIE ou do estabelecimento, especialmente no descumprimento dos prazos de execução de inspeções ou recomendações de inspeção."}, {"c": "dou-paragraph", "t": "11.2.1 A advertência deve ser formalizada pelo OCP e não implica na redução dos prazos de inspeção ou de qualquer alteração na aplicação dos itens constantes na NR-13 para estabelecimentos com SPIE certificado."}, {"c": "dou-paragraph", "t": "11.3 A suspensão do certificado do SPIE, por tempo indeterminado, deve ocorrer quando:"}, {"c": "dou-paragraph", "t": "a) deixar de atender ou eliminar, dentro do prazo estabelecido, as causas que concorreram para a advertência;"}, {"c": "dou-paragraph", "t": "b) deixar de tratar uma não conformidade Categoria A RGI;"}, {"c": "dou-paragraph", "t": "c) reincidir em não conformidades de mesma causa específica em requisito que anteriormente acarretou advertência no mesmo ciclo;"}, {"c": "dou-paragraph", "t": "d) casos excepcionais nos quais o OCP julgue pela aplicação de suspensão."}, {"c": "dou-paragraph", "t": "11.3.1 A suspensão impossibilita a divulgação da certificação pelo estabelecimento e deve ser divulgada em todos os meios de comunicação utilizados pelo OCP. Em particular, o OCP deve informar a suspensão aos órgãos de fiscalização competentes e à representação sindical da categoria profissional predominante no estabelecimento."}, {"c": "dou-paragraph", "t": "11.3.2 A suspensão não implica na redução imediata dos prazos de inspeção ou qualquer alteração na aplicação dos itens constantes na NR-13 para estabelecimentos com SPIE certificado."}, {"c": "dou-paragraph", "t": "11.3.3 Cabe ao OCP definir as atividades de avaliação necessárias para o restabelecimento da certificação."}, {"c": "dou-paragraph", "t": "11.4 O cancelamento do certificado exclui o estabelecimento da condição de SPIE certificado nas seguintes circunstâncias quando o SPIE:"}, {"c": "dou-paragraph", "t": "a) deixar de atender ou eliminar as causas de uma suspensão no prazo acordado;"}, {"c": "dou-paragraph", "t": "b) reincidir em itens que levaram a uma suspensão dentro de um mesmo ciclo de certificação;"}, {"c": "dou-paragraph", "t": "d) casos excepcionais nos quais o OCP julgue pela aplicação de cancelamento."}, {"c": "dou-paragraph", "t": "11.4.1 O cancelamento deve ser formalizado e divulgado em todos os meios de comunicação utilizados pelo OCP. Em particular, o OCP deve informar o cancelamento aos órgãos de fiscalização competentes e à representação sindical da categoria profissional predominante no estabelecimento."}, {"c": "dou-paragraph", "t": "11.4.2 Os prazos estabelecidos pelo PLH antes do cancelamento, respeitados os limites normativos legais, para as inspeções de segurança dos equipamentos enquadrados na NR-13 continuam válidos até a execução dessas inspeções; a partir daí, passarão a vigorar os prazos previstos na NR-13 para estabelecimentos sem certificação de SPIE."}, {"c": "dou-paragraph", "t": "11.4.3 Em caso de cancelamento, o estabelecimento somente deve solicitar novo processo de certificação após 18 (dezoito) meses a partir da data de aplicação da penalidade."}, {"c": "dou-paragraph", "t": "12. DENÚNCIAS, RECLAMAÇÕES E SUGESTÕES"}, {"c": "dou-paragraph", "t": "Os critérios para denúncias, reclamações e sugestões devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "ANEXO A - REQUISITOS PARA A FORMAÇÃO E EXERCÍCIO DA ATIVIDADE DE AUDITOR DE SPIE PELO OCP"}, {"c": "dou-paragraph", "t": "1. OBJETIVO"}, {"c": "dou-paragraph", "t": "Este Anexo estabelece os requisitos a serem atendidos para a formação e exercício da atividade de auditores que atuam no processo de certificação de SPIE pelo OCP, conforme previsto neste RAC."}, {"c": "dou-paragraph", "t": "2. REQUISITOS PARA A FORMAÇÃO DE AUDITORES DE SPIE"}, {"c": "dou-paragraph", "t": "2.1 Curso para Capacitação de Auditores de SPIE"}, {"c": "dou-paragraph", "t": "2.1.1 O candidato a auditor deve ter frequência plena e ser aprovado em curso de formação de auditor de SPIE, ministrado por OCP de SPIE mediante avaliação de seu aproveitamento por meio de prova escrita."}, {"c": "dou-paragraph", "t": "2.1.2 O curso deve ter uma carga horária total mínima de 52 (cinquenta e duas) horas."}, {"c": "dou-paragraph", "t": "2.1.3 A Tabela 1 apresenta o conteúdo programático mínimo a ser abordado."}, {"c": "dou-paragraph", "t": "2.2 Escolaridade"}, {"c": "dou-paragraph", "t": "O candidato deve comprovar, no mínimo, formação em nível médio, sendo obrigatória a formação técnica em área reconhecida pelos respectivos Conselhos de Classe."}, {"c": "dou-paragraph", "t": "Nota: Para comprovação de escolaridade será exigida a apresentação de cópia do diploma ou certificado de conclusão de curso fornecido por entidade reconhecida oficialmente, acompanhado do original."}, {"c": "dou-paragraph", "t": "2.3 Experiência Profissional"}, {"c": "dou-paragraph", "t": "2.3.1 Candidato de nível superior: deve possuir, no mínimo, 10 (dez) anos de experiência profissional comprovada, na atividade de inspeção de equipamentos em operação, sendo desejável atuação em cargo de coordenação."}, {"c": "dou-paragraph", "t": "2.3.2 Candidato de nível médio: deve possuir, no mínimo, 12 (doze) anos de experiência profissional comprovada, nas atividades de inspeção de equipamentos em operação."}, {"c": "dou-paragraph", "t": "Tabela 1 Conteúdo programático mínimo do curso de formação"}, {"c": "", "t": "MÓDULO"}, {"c": "", "t": "ASSUNTO"}, {"c": "", "t": "Horas"}, {"c": "", "t": "Aspectos legais da atividade de Inspeção de Equipamentos e histórico"}, {"c": "", "t": "2"}, {"c": "", "t": "Conceitos básicos sobre avaliação da conformidade ABNT ISO 17075"}, {"c": "", "t": "4"}, {"c": "", "t": "Parte Teórica"}, {"c": "", "t": "Psicologia da Auditoria e Comportamento do Auditor"}, {"c": "", "t": "4"}, {"c": "", "t": "Portarias Inmetro de SPIE"}, {"c": "", "t": "4"}, {"c": "", "t": "Procedimentos de Auditoria de SPIE"}, {"c": "", "t": "6"}, {"c": "", "t": "Total da Parte Teórica"}, {"c": "", "t": "20"}, {"c": "", "t": "Planejamento e Análise das Informações Preliminares"}, {"c": "", "t": "5"}, {"c": "", "t": "Análise da Programação e do Efetivo"}, {"c": "", "t": "5"}, {"c": "", "t": "Parte Prática"}, {"c": "", "t": "Verificação de Documentação e Arquivos"}, {"c": "", "t": "5"}, {"c": "", "t": "Verificação de requisitos de campo e laboratórios"}, {"c": "", "t": "5"}, {"c": "", "t": "Preenchimento da lista de verificação e constatações"}, {"c": "", "t": "4"}, {"c": "", "t": "Entrevistas"}, {"c": "", "t": "4"}, {"c": "", "t": "Reuniões de Abertura e Encerramento"}, {"c": "", "t": "4"}, {"c": "", "t": "Total da Parte Prática"}, {"c": "", "t": "32"}, {"c": "dou-paragraph", "t": "3. REQUISITOS PARA O EXERCÍCIO DA ATIVIDADE"}, {"c": "dou-paragraph", "t": "3.1 O auditor de SPIE fica impedido de prestar consultoria ou treinamento, cujo tema principal seja certificação de SPIE, direta ou indiretamente, para qualquer estabelecimento que esteja postulando ou que possua SPIE, durante o período em que estiver vinculado ao OCP."}, {"c": "dou-paragraph", "t": "3.2 O profissional que concluir o curso de formação de auditores de SPIE com aproveitamento satisfatório deve acompanhar, sob supervisão, auditorias que contemplem todas as etapas estabelecidas no RAC para SPIE, de forma a demonstrar sua competência técnica e serem realizadas num período inferior a 24 (vinte e quatro) meses contados a partir do término do curso."}, {"c": "dou-paragraph", "t": "3.3 O profissional deve participar de ao menos 5 (cinco) auditorias supervisionadas, realizadas por OCP acreditado, por entidade formadora ou organismo em processo de acreditação."}, {"c": "dou-paragraph", "t": "3.4 Durante o treinamento, o profissional não poderá atuar de forma autônoma, e sua qualificação ficará condicionada à avaliação de desempenho pelos auditores líderes e pelo OCP."}, {"c": "anexo", "t": "ANEXO B - LISTA DE VERIFICAÇÃO PARA AUDITORIAS DE SPIE"}, {"c": "dou-paragraph", "t": "Este Anexo tem caráter meramente referencial e visa facilitar a organização e rastreabilidade dos requisitos aplicáveis às auditorias de SPIE."}, {"c": "", "t": "Nº"}, {"c": "", "t": "Referência"}, {"c": "", "t": "Origem"}, {"c": "", "t": "Descrição do Requisito"}, {"c": "", "t": "Tipo"}, {"c": "", "t": "Frequência"}, {"c": "", "t": "1."}, {"c": "", "t": "5."}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "O SPIE deve ser um órgão fisicamente constituído e integrado à estrutura administrativa."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "InicialRecertificação"}, {"c": "", "t": "2."}, {"c": "", "t": "5.1.1"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "O SPIE deve ter um responsável formalmente designado para gestão da inspeção."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Todas"}, {"c": "", "t": "3."}, {"c": "", "t": "5.1.2"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "O responsável pelo SPIE deve ter autoridade técnica e autonomia e não exercer funções conflitantes."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Todas"}, {"c": "", "t": "4."}, {"c": "", "t": "5.1.3.1"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "O SPIE deve possuir quadro próprio com formação e dedicação compatíveis."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Todas"}, {"c": "", "t": "5."}, {"c": "", "t": "5.1.3.4.1"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "O SPIE deve possuir no mínimo um PLH."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Todas"}, {"c": "", "t": "6."}, {"c": "", "t": "5.1.3.5"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "O efetivo mínimo do SPIE deve atender aos critérios definidos no Anexo A."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Todas"}, {"c": "", "t": "7."}, {"c": "", "t": "5.1.3.7"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Requisitos de capacitação devem seguir o Anexo B da INI-SPIE"}, {"c": "", "t": "A comum"}, {"c": "", "t": "Todas"}, {"c": "", "t": "8."}, {"c": "", "t": "5.1.3.8"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "O SPIE deve implementar programa de treinamento para seus integrantes"}, {"c": "", "t": "B comum"}, {"c": "", "t": "Manutenção / Recertificação"}, {"c": "", "t": "9."}, {"c": "", "t": "5.1.3.9"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "A contratação de mão de obra, ou serviços, deve restringir-se a requisitos da INI-SPIE."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Manutenção / Recertificação"}, {"c": "", "t": "10."}, {"c": "", "t": "5.1.3.9 e 5.1.3.10"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "A mão de obra contratada deve ser selecionada com critérios semelhantes ao da mão de obra própria. Os inspetores de END, soldagem e pintura devem seguir as qualificações e certificações aplicáveis."}, {"c": "", "t": "B"}, {"c": "", "t": "Manutenção / Recertificação"}, {"c": "", "t": "11."}, {"c": "", "t": "6"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Todos os itens, sob controle do SPIE, devem estar incluídos em seu programa de inspeção e se atende as exigências legais e normativas."}, {"c": "", "t": "B"}, {"c": "", "t": "Todas"}, {"c": "", "t": "12."}, {"c": "", "t": "7.1 a"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "O SPIE deve manter lista atualizada dos equipamentos sob controle."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Todas"}, {"c": "", "t": "13."}, {"c": "", "t": "7.1 d"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "O SPIE deve manter lista atualizada de equipamentos de terceiros."}, {"c": "", "t": "B"}, {"c": "", "t": "Manutenção"}, {"c": "", "t": "14."}, {"c": "", "t": "7.1 b"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "O SPIE deve manter lista de equipamentos temporariamente fora de operação, em hibernação ou reserva."}, {"c": "", "t": "B"}, {"c": "", "t": "Manutenção"}, {"c": "", "t": "15."}, {"c": "", "t": "7.1 d"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "O SPIE deve certificar se o programa de inspeção, registros de segurança e recomendações de inspeção de equipamentos de terceiros estejam sendo cumpridos."}, {"c": "", "t": "B"}, {"c": "", "t": "Manutenção"}, {"c": "", "t": "16."}, {"c": "", "t": "7.1 e"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "O SPIE deve assegurar realização de ensaios e testes para avaliar as condições dos equipamentos sob seu controle."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Todas"}, {"c": "", "t": "17."}, {"c": "", "t": "7.1 f"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Decidir se os equipamentos sob seu controle têm condição satisfatória e divulgar os resultados para os envolvidos."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Todas"}, {"c": "", "t": "18."}, {"c": "", "t": "7.1 g"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "O SPIE deve emitir parecer técnico e recomendar ações corretivas."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Todas"}, {"c": "", "t": "19."}, {"c": "", "t": "7.1 g"}, {"c": "", "t": "IN-SPIE"}, {"c": "", "t": "O SPIE deve registrar e controlar os prazos e providências das recomendações emitidas, com determinação de prioridades, prazos e responsáveis pela execução, incluindo o registro e controle de eventuais reavaliações."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Todas"}, {"c": "", "t": "20."}, {"c": "", "t": "7.1 Nota 1"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Os casos de reavaliação devem estabelecer o procedimento, os critérios e os responsáveis pela aprovação dos novos prazos."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Todas"}, {"c": "", "t": "21."}, {"c": "", "t": "7.1 h"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "O SPIE deve utilizar técnicas e métodos de inspeção preventiva para monitorar os seus equipamentos."}, {"c": "", "t": "B"}, {"c": "", "t": "Manutenção"}, {"c": "", "t": "22."}, {"c": "", "t": "7.1 i"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Manter a atualização e rastreabilidade dos registros de inspeção."}, {"c": "", "t": "B"}, {"c": "", "t": "Todas"}, {"c": "", "t": "23."}, {"c": "", "t": "7.1 j"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Determinar a vida remanescente dos itens sob seu controle, devendo a dispensa ser justificada para qualquer item controlado."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Manutenção / Recertificação"}, {"c": "", "t": "24."}, {"c": "", "t": "7.1 k"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Participar de decisões ou desenvolver estudos técnicos para definir se itens sob seu controle podem operar de forma segura em condições distintas do projeto."}, {"c": "", "t": "B"}, {"c": "", "t": "Inicial / Recertificação."}, {"c": "", "t": "25."}, {"c": "", "t": "7.1 l"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Efetuar, testemunhar, ou assegurar a verificação de condições físicas e de desempenho dos dispositivos de segurança."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Todas"}, {"c": "", "t": "26."}, {"c": "", "t": "7.1 m"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Assegurar ou realizar ensaios testes e medições para verificar a qualidade de reparos ou modificações executadas nos itens sob seu controle."}, {"c": "", "t": "B"}, {"c": "", "t": "Inicial / Recertificação"}, {"c": "", "t": "27."}, {"c": "", "t": "7.1 n"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Possuir procedimentos para as principais atividades de inspeção, incluindo testes, ensaios, exames e medições que devem ser executados."}, {"c": "", "t": "B"}, {"c": "", "t": "Inicial / Recertificação"}, {"c": "", "t": "28."}, {"c": "", "t": "7.1 o"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Divulgar entre pessoal próprio e contratado os procedimentos atualizados."}, {"c": "", "t": "B"}, {"c": "", "t": "Recertificação"}, {"c": "", "t": "29."}, {"c": "", "t": "7.1 p e 9.1"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Definir critérios para contratação e avaliação de serviços de inspeção."}, {"c": "", "t": "B"}, {"c": "", "t": "Recertificação"}, {"c": "", "t": "30."}, {"c": "", "t": "7.1 r"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Executar, testemunhar, ou assegurar, por meio de evidências documentadas, que as atividades de inspeção de fabricação, recebimento de equipamentos ou sobressalentes e de montagem estão sendo realizadas."}, {"c": "", "t": "B"}, {"c": "", "t": "Inicial / Recertificação"}, {"c": "", "t": "31."}, {"c": "", "t": "7.1 s"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "O SPIE deve participar de comissões para identificar, analisar e investigar eventos indesejados."}, {"c": "", "t": "B"}, {"c": "", "t": "Recertificação"}, {"c": "", "t": "32."}, {"c": "", "t": "7.1 t e 10.1"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Manter lista atualizada da aparelhagem de inspeção, inclusive daquelas não sujeitas à calibração, assegurando condições adequadas de preservação."}, {"c": "", "t": "B"}, {"c": "", "t": "Inicial / Recertificação"}, {"c": "", "t": "33."}, {"c": "", "t": "7.1 u;7.1 v; 10.2 e 10.5"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Efetuar ou providenciar a calibração da aparelhagem de inspeção contra padrões rastreáveis, mantendo seus registros."}, {"c": "", "t": "B"}, {"c": "", "t": "Inicial / Recertificação"}, {"c": "", "t": "34."}, {"c": "", "t": "7.1 w; 10.3 e 10.4"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Possuir procedimentos para controle da aparelhagem incluindo a segregação e análise da validade dos resultados."}, {"c": "", "t": "B"}, {"c": "", "t": "Inicial / Recertificação"}, {"c": "", "t": "35."}, {"c": "", "t": "7.1 x"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Participar de comissões para identificação de causas de falhas em itens sob seu controle."}, {"c": "", "t": "B"}, {"c": "", "t": "Recertificação"}, {"c": "", "t": "36."}, {"c": "", "t": "7.1 y"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Divulgar para força de trabalho, de forma compreensível, seus objetivos e metas."}, {"c": "", "t": "B"}, {"c": "", "t": "Recertificação"}, {"c": "", "t": "37."}, {"c": "", "t": "7.3 e Anexo C"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Sistemas Instrumentados de Segurança (SIS), onde implementados atendem os requisitos da NR-13."}, {"c": "", "t": "B"}, {"c": "", "t": "Recertificação"}, {"c": "", "t": "38."}, {"c": "", "t": "Anexo C"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Sistemas Instrumentados de Segurança (SIS) mantém as premissas aprovadas."}, {"c": "", "t": "B"}, {"c": "", "t": "Manutenção"}, {"c": "", "t": "39."}, {"c": "", "t": "7.2.3 e Anexo D"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Inspeção Baseada em Risco (IBR), onde implementada, atende os requisitos da NR-13."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Recertificação"}, {"c": "", "t": "40."}, {"c": "", "t": "Anexo D"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Se a Inspeção Baseada em Risco (IBR) mantém as premissas aprovadas."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Manutenção"}, {"c": "", "t": "41."}, {"c": "", "t": "7.2.3 e Anexo E"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Se a Inspeção Não Intrusiva (INI), onde implementada, atende os requisitos da NR-13."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Recertificação"}, {"c": "", "t": "42."}, {"c": "", "t": "Anexo E"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Se a Inspeção Não Intrusiva (INI) mantem as premissas aprovadas."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Manutenção"}, {"c": "", "t": "43."}, {"c": "", "t": "8.1"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "O SPIE deve ter um procedimento para controle de seus documentos e registros"}, {"c": "", "t": "B"}, {"c": "", "t": "Inicial / Recertificação"}, {"c": "", "t": "44."}, {"c": "", "t": "8.2"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "O sistema de documentação e registro do SPIE tem a abrangência requerida."}, {"c": "", "t": "B"}, {"c": "", "t": "Inicial / Recertificação"}, {"c": "", "t": "45."}, {"c": "", "t": "8.2"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "A identificação dos equipamentos é correta, clara e facilmente visível, conforme procedimento do estabelecimento."}, {"c": "", "t": "B"}, {"c": "", "t": "Todas"}, {"c": "", "t": "46."}, {"c": "", "t": "8.4"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Os registros, quando requeridos na INI-SPIE, são assinados pelo PLH"}, {"c": "", "t": "B"}, {"c": "", "t": "Todas"}, {"c": "", "t": "47."}, {"c": "", "t": "8.4.2 e 8.4.3"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "Os relatórios de inspeção consolidados atendem as exigências legais."}, {"c": "", "t": "B"}, {"c": "", "t": "Todas"}, {"c": "", "t": "48."}, {"c": "", "t": "11.1 e 11.2"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "O SPIE deve realizar auditorias internas conforme programação e procedimento aplicável."}, {"c": "", "t": "B"}, {"c": "", "t": "Todas"}, {"c": "", "t": "49."}, {"c": "", "t": "11.3"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "A CIPA, e a Representação Sindical devem ser convidadas para participar da entrevista da auditoria interna."}, {"c": "", "t": "B"}, {"c": "", "t": "Manutenção e Recertificação"}, {"c": "", "t": "50."}, {"c": "", "t": "12.1"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "O SPIE deve possuir procedimento para tratamento de Não Conformidades e Preocupações."}, {"c": "", "t": "B"}, {"c": "", "t": "Inicial / Recertificação"}, {"c": "", "t": "51."}, {"c": "", "t": "12.2"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "As Não Conformidades e Preocupações devem ser tratadas."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Todas"}, {"c": "", "t": "52."}, {"c": "", "t": "13.1"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "A análise crítica dos resultados do SPIE deve ser periódica, com registro formal e atender as exigências da INI-SPIE."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Todas"}, {"c": "", "t": "53."}, {"c": "", "t": "14.1 e 14.2"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "O SPIE deve possuir procedimentos, abrangendo clientes internos, para tratamento de reclamações de seus serviços."}, {"c": "", "t": "B"}, {"c": "", "t": "Recertificação e Manutenção"}, {"c": "", "t": "54."}, {"c": "", "t": "14.3"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "O SPIE deve divulgar para toda força de trabalho e público externo o canal ou outro meio para registro de reclamação."}, {"c": "", "t": "B"}, {"c": "", "t": "Recertificação e Manutenção"}, {"c": "", "t": "55."}, {"c": "", "t": "14.4"}, {"c": "", "t": "INI-SPIE"}, {"c": "", "t": "O SPIE deve manter registros das reclamações recebidas com conteúdo previsto na INI-SPIE."}, {"c": "", "t": "B"}, {"c": "", "t": "Recertificação e Manutenção"}, {"c": "", "t": "56."}, {"c": "", "t": "6.3.1.1.3"}, {"c": "", "t": "RAC"}, {"c": "", "t": "As informações preliminares para auditoria devem ser encaminhadas em até trinta dias antes do início da auditoria e o seu conteúdo deve estar conforme o RAC."}, {"c": "", "t": "B"}, {"c": "", "t": "Todas"}, {"c": "", "t": "57."}, {"c": "", "t": "6.3.1.6.3a"}, {"c": "", "t": "RAC"}, {"c": "", "t": "A localização e as características dos itens controlados pelo SPIE conferem com o prescrito na documentação."}, {"c": "", "t": "B"}, {"c": "", "t": "Todas"}, {"c": "", "t": "58."}, {"c": "", "t": "6.3.1.6.5c"}, {"c": "", "t": "RAC"}, {"c": "", "t": "A categoria do equipamento, quando aplicável, está correta e atende as exigências da NR-13."}, {"c": "", "t": "B"}, {"c": "", "t": "Todas"}, {"c": "", "t": "59."}, {"c": "", "t": "6.3.1.6.5d"}, {"c": "", "t": "RAC"}, {"c": "", "t": "As placas de identificação estão devidamente afixadas, são acessíveis e visíveis, e atendem aos requisitos legais e normativos."}, {"c": "", "t": "B"}, {"c": "", "t": "Todas"}, {"c": "", "t": "60."}, {"c": "", "t": "6.3.1.6.5f"}, {"c": "", "t": "RAC"}, {"c": "", "t": "Se os manômetros, indicadores de pressão e ou transmissores de pressão, dos itens enquadrados na NR-13 estão identificados."}, {"c": "", "t": "B"}, {"c": "", "t": "Todas"}, {"c": "", "t": "61."}, {"c": "", "t": "6.3.1.6.5f"}, {"c": "", "t": "RAC"}, {"c": "", "t": "Os manômetros, indicadores de pressão e ou transmissores de pressão, dos itens enquadrados na NR-13 reúnem condições operacionais aceitáveis e possuem planos de calibração vigentes."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Todas"}, {"c": "", "t": "62."}, {"c": "", "t": "6.3.1.6.5f"}, {"c": "", "t": "RAC"}, {"c": "", "t": "Os indicadores de nível de caldeiras reúnem condições operacionais aceitáveis, estão identificados. Caso algum visor não esteja operacional os instrumentos alternativos ao visor de nível, devem estar funcionais e possuir planos de calibração vigente."}, {"c": "", "t": "A RGI"}, {"c": "", "t": "Todas"}, {"c": "", "t": "63."}, {"c": "", "t": "6.3.1.6.5g"}, {"c": "", "t": "RAC"}, {"c": "", "t": "A calibração dos instrumentos deve seguir plano de manutenção preventiva e os procedimentos aplicáveis. A oficina de calibração de instrumentos dever atender às necessidades do serviço."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Todas"}, {"c": "", "t": "64."}, {"c": "", "t": "6.3.1.6.5h"}, {"c": "", "t": "RAC"}, {"c": "", "t": "O equipamento amostrado apresenta vazamento ou deterioração que possa provocar acidente iminente e não possua recomendação de inspeção vigente."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Todas"}, {"c": "", "t": "65."}, {"c": "", "t": "6.3.1.6.6i"}, {"c": "", "t": "RAC"}, {"c": "", "t": "O acesso ao equipamento é seguro e apresenta bom estado de conservação."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Todas"}, {"c": "", "t": "66."}, {"c": "", "t": "6.3.1.6.5e e 6.3.1.6.5j"}, {"c": "", "t": "RAC"}, {"c": "", "t": "Se existem dispositivos de segurança, se não estão bloqueados inadvertidamente e se o valor de PMTA do equipamento é compatível com a pressão de abertura do dispositivo de segurança."}, {"c": "", "t": "A RGI"}, {"c": "", "t": "Todas"}, {"c": "", "t": "67."}, {"c": "", "t": "6.3.1.6.5e"}, {"c": "", "t": "RAC"}, {"c": "", "t": "Se existe dispositivo contra bloqueio inadvertido dos dispositivos de segurança."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Todas"}, {"c": "", "t": "68."}, {"c": "", "t": "6.3.1.6.5e"}, {"c": "", "t": "RAC"}, {"c": "", "t": "Se os dispositivos de segurança estão lacrados."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Todas"}, {"c": "", "t": "69."}, {"c": "", "t": "6.3.1.6.5k"}, {"c": "", "t": "RAC"}, {"c": "", "t": "As inspeções e intervenções estão sendo adequadamente anotadas no registro de segurança e se confere com as existentes no arquivo do SPIE."}, {"c": "", "t": "B"}, {"c": "", "t": "Todas"}, {"c": "", "t": "70."}, {"c": "", "t": "6.6.1a"}, {"c": "", "t": "RAC"}, {"c": "", "t": "As ocorrências em equipamentos controlados pelo SPIE, listadas na RAC, são comunicadas formalmente ao OCP no prazo previsto pelo RAC."}, {"c": "", "t": "B"}, {"c": "", "t": "Manutenção e Recertificação"}, {"c": "", "t": "71."}, {"c": "", "t": "6.6.3"}, {"c": "", "t": "RAC"}, {"c": "", "t": "Se alterações de perfil estão sendo comunicadas, no prazo determinado no RAC, estão sendo comunicadas ao OCP."}, {"c": "", "t": "B"}, {"c": "", "t": "Manutenção Recertificação"}, {"c": "", "t": "72."}, {"c": "", "t": "6.3.1.6.5l"}, {"c": "", "t": "RAC"}, {"c": "", "t": "Os itens controlados pelo SPIE, incluídos no programa de inspeção, devem ser rastreáveis com as instalações físicas."}, {"c": "", "t": "A Comum"}, {"c": "", "t": "Todas"}, {"c": "", "t": "73."}, {"c": "", "t": "6.2.3.6.8"}, {"c": "", "t": "RAC"}, {"c": "", "t": "O Cipista entrevistado deve atender aos critérios estabelecidos no RAC."}, {"c": "", "t": "B"}, {"c": "", "t": "Todas"}]});